import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/software-exam/ispm/project-resource-management/comprehensive-exercises/","title":"10 综合练习 | 软考","lang":"zh-CN","frontmatter":{"title":"10 综合练习","createTime":"2026-11-22T21:20:00.000Z","permalink":"/software-exam/ispm/project-resource-management/comprehensive-exercises/","outline":false,"aside":false},"readingTime":{"minutes":118.91,"words":35673},"git":{"createdTime":1795354081000},"filePathRelative":"software-exam/ispm/project-resource-management/10.comprehensive-exercises.md","headers":[],"bulletin":false}`),a={name:`10.comprehensive-exercises.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="exam-note"><p><a id="q1" class="quiz-anchor"></a></p><p><strong>1.</strong> 项目经理对于（ ）的冲突要设法加以（ ）;对（ ）的冲突要加以利用，要鼓励团队成员良性竟争。</p><ul><li>A．有害，解决或减少，有益</li><li>B．有益，解决或减少，有害</li><li>C．有害，解决或增加，有益</li><li>D．有益，鼓励或增加，有害</li></ul><details class="quiz" data-q="1" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目经理对于有害的冲突要设法加以解决或减少；对有益的冲突要加以利用，要鼓励团队成员良性竟争（P382）　<span class="quiz-src">教材第 13 章章节习题</span></p></details><p><a id="q2" class="quiz-anchor"></a></p><p><strong>2.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．实物资源管理着眼于以有效和高效的方式，分配和使用完成项目所需的实物资源，包括设备、材料、设施和人力</li><li>B．团队资源指的是人力资源，团队资源管理相对于实物资源管理，包含了技能和能力要求</li><li>C．管理团队过程重点关注人力资源</li><li>D．控制资源过程重点关注实物资源</li></ul><details class="quiz" data-q="2" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O。实物资源管理着服于以有效和高效的方式，分配和使用完成项目所需的实物资源，包括设备材料、设施和基础设施。团队资源指的是人力资源，团队资源管理相对于实物资源管理，包含了技能和能力要求（P38）　<span class="quiz-src">自编</span></p></details><p><a id="q3" class="quiz-anchor"></a></p><p><strong>3.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．设备、材料、设施属于实物资源。</li><li>B．团队资源管理相对于实物资源管理，包含了技能和能力要求。</li><li>C．项目团队成员可以是兼职的。</li><li>D．团队资源指的是人力资源，包括人员所使用的设备，居住条件等。</li></ul><details class="quiz" data-q="3" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：380。团队资源指的是人力资源。人员所使用的设备，居住条件，这些是实物资源　<span class="quiz-src">自编</span></p></details><p><a id="q4" class="quiz-anchor"></a></p><p><strong>4.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．对于小型项目，项目管理职责可由整个项目团队分担，或者由项目经理独自承担</li><li>B．团队成员在规划阶段就参与进来，既可使他们对项目规划工作贡献专业技能，又可以增强他们对项目的责任感。</li><li>C．项目经理是由执行组织委派，领导项目团队实现项目目标的个人。</li><li>D．职业道德是个人的素养，和自身有关，项目经理无权干涉。</li></ul><details class="quiz" data-q="4" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理还应留意并支持职业与道德行为，确保所有团队成员都遵守这些行为（P381）　<span class="quiz-src">自编</span></p></details><p><a id="q5" class="quiz-anchor"></a></p><p><strong>5.</strong> 项目资源管理中对团队进行有效的指导和管理，以保证团队可以完成项目任务，关于项目资源的描述，正确的是（ ）。</p><ul><li>A．新成员加入到项目团队中，他们的经验水平将会降低项目风险</li><li>B．项目资源管理包括规划资源管理、组建项目团队、建设项目团队三个过程</li><li>C．项目经理对于所有冲突要设法解决或减少，鼓励团队成员良性竞争</li><li>D．项目团队中项目经理的领导能力和管理能力二者缺一不可</li></ul><details class="quiz" data-q="5" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：A错误。新成员加入到项目团队中，他们的经验水平往往不高，对项目也不然悉，将会增加项目风险。B错误。项目资源管理包括规划资源管理、估算活动资源、获取资源、建设团队、管理团队和控制资源六个过程（P381）　<span class="quiz-src">自编</span></p></details><p><a id="q6" class="quiz-anchor"></a></p><p><strong>6.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．领导者确定方向，统一思想，激励和鼓舞</li><li>B．领导者设定目标，管理者率众实现目标</li><li>C．尊重和信任，而非畏惧和顺从，是有效领导力的关键要素</li><li>D．项目经理是团队的领导者而非管理者，需要加强领导力的锻炼</li></ul><details class="quiz" data-q="6" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理具有领导者和管理者的双重身份。对项目经理面言，管理能力和领导能力二者均不可或缺。对于大型复杂项目，领导能力尤为重要（P381）　<span class="quiz-src">自编</span></p></details><p><a id="q7" class="quiz-anchor"></a></p><p><strong>7.</strong> 下面哪种权力来源于个人自身（ ）。</p><ul><li>A．职位权力</li><li>B．惩罚权力</li><li>C．奖励权力</li><li>D．专家权力</li></ul><details class="quiz" data-q="7" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：职位权力、惩罚权力、奖励权力来自于组织的授权，专家权力和参照权力来自于管理者自身（P381-382）　<span class="quiz-src">自编</span></p></details><p><a id="q8" class="quiz-anchor"></a></p><p><strong>8.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．冲突是指两个或两个以上的社会单元在目标上互不相容或互相排斥，从而产生心理上的或行为上的矛盾</li><li>B．竞争的双方则具有同一个目标，不需要发生势不两立的争夺</li><li>C．冲突并不一定是有害的，“一团和气”的集体不一定是一个高效率的集体</li><li>D．项目经理要尽量避免团队冲突，保持团队积极向上</li></ul><details class="quiz" data-q="8" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：冲突并不一定是有害的，“一团和气”的集体不一定是一个高效率的集体。项目经理对于有害的冲突要设法加以解决或减少；对有益的冲突要加以利用，要鼓励团队成员良性竞金（P382）　<span class="quiz-src">自编</span></p></details><p><a id="q9" class="quiz-anchor"></a></p><p><strong>9.</strong> 团队往往对未来有美好的期待，属于团队发展阶段的（ ）。</p><ul><li>A．形成阶段</li><li>B．震荡阶段</li><li>C．规范阶段</li><li>D．发挥阶段</li></ul><details class="quiz" data-q="9" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：阶段 解释说明形成阶段 一个个的个体转变为团队成员。团队往往对未来有美好的期待。震荡阶段 个体之间开始争执，互相指责，并且开始怀疑项目经理的能力（P382-383）　<span class="quiz-src">自编</span></p></details><p><a id="q10" class="quiz-anchor"></a></p><p><strong>10.</strong> 在马斯洛需求层次中，底层的四种需求不包括（ ）。</p><ul><li>A．安全需求</li><li>B．社会交往需求</li><li>C．受尊重的需求</li><li>D．自我实现的需求</li></ul><details class="quiz" data-q="10" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：在马斯洛需求层次中，底层的4种需求即生理、安全、社会交往、受尊重被认为是基本的需求，而自我实现是最高层次的需求。马斯洛需求层次理论定义雷求层次 常见的激励措施对衣食住行等需求，最低级别的基本 员工宿含、工作餐、工作服、班车、生理需求 需求 工资、补贴、奖金对人身安全、生活稳定、不致失业以 养老保险、医疗保障、长期劳动合同、安全需求 及免遭痛苦、威胁或疾病等的需求（P383-384）　<span class="quiz-src">自编</span></p></details><p><a id="q11" class="quiz-anchor"></a></p><p><strong>11.</strong> （ ）是与工作环境或条件有关，可消除不满但无法起到激励作用的因素</p><ul><li>A．激励因素</li><li>B．保健因素</li><li>C．期望因素</li><li>D．效价因素</li></ul><details class="quiz" data-q="11" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：保健因素是与工作环境或条件有关的，包括工作环境、工资薪水、公司政策、个人生活、管理监督、人际关系等。保健因素可以消除不满，但无法起到激励作用（P384）　<span class="quiz-src">自编</span></p></details><p><a id="q12" class="quiz-anchor"></a></p><p><strong>12.</strong> 属于激励因素的是（ ）。</p><ul><li>A．工资薪水</li><li>B．人际关系</li><li>C．个人生活</li><li>D．工作本身</li></ul><details class="quiz" data-q="12" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：激励因素是与员工的工作本身或工作内容有关的，能促使人们产生工作满意感的一类因素，是高层次的需要，包括成就、承认、工作本身、责任、发展机会等（P384-385）　<span class="quiz-src">自编</span></p></details><p><a id="q13" class="quiz-anchor"></a></p><p><strong>13.</strong> 关于X理论和Y理论的描述不正确的是（ ）</p><ul><li>A．X理论认为对员工采取强制惩罚和解雇等手段，强迫员工努力工作</li><li>B．Y理论认为应将员工目标和组织目标结合，发挥员工的智慧和能力</li><li>C．用X理论可以加强管理，用Y理论可以激发员工主动性</li><li>D．项目初始阶段建议运用Y理论，执行阶段建议运用X理论</li></ul><details class="quiz" data-q="13" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：在项目团队的开始阶段，大家互相还不是很熟悉，对项目不是很了解或者还有某种抵触等，这时候需要项目经理运用X理论去指导和管理；当项目团队进入执行阶段，成员对项目的目标已经了解，都愿意努力完成项目，这时候可以运用Y理论授权团队完成所负责的工作，并提供支持和相应的环境（P385）　<span class="quiz-src">自编</span></p></details><p><a id="q14" class="quiz-anchor"></a></p><p><strong>14.</strong> （ ）属于人力资源管理中的Y理论</p><ul><li>A．一般人天性好逸恶劳，只要有可能就会逃避工作</li><li>B．在适当的条件下，人们愿意主动承担责任</li><li>C．人缺乏进取心逃避职责，甘愿听从指挥安于现状，没有创新性</li><li>D．人生来就以自我为中心，漠视组织的要求</li></ul><details class="quiz" data-q="14" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：Y理论对人性的假设与×理论完全相反，其主要观点如下：①人天生并不是好遍恶劳，他们热爱工作，从工作得到满足感和成就感；②外来的控制和处罚对人们实现组织的目标不是一个有效的办法，下属能够自我确定目标、自我指挥和自我控制；③在适当的条件下，人们愿意主动承担责任；④大多数人具有一定的想象力和创渣力；⑥在现代社会中，人们的智慧和潜能只是部分地得到了发挥，如果给予机公，人们喜欢工作，并渴望发挥其才能（P385）　<span class="quiz-src">自编</span></p></details><p><a id="q15" class="quiz-anchor"></a></p><p><strong>15.</strong> 期望理论是一种通过考察人们的努力行为与其所获得的最终奖酬之间的因果关系，来说明激励过程，并以选择合适的行为达到最终的奖酬目标的理论，以下关于期望理论的说法中不正确的是（ ）</p><ul><li>A．期望理论认为，一个目标对人的激励程度受目标效价和期望值2个因素影响</li><li>B．目标效价指实现该目标对个人有多大价值的科学、客观的判断。如果实现该目标对个人来说很有价值，个人的积极性就高</li><li>C．期望值指个人对实现该目标可能性大小的主观估计</li><li>D．期望理论认为，激励水平等于目标效价和期望值的乘积</li></ul><details class="quiz" data-q="15" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：目标效价指实现该目标对个人有多大价值的主观判断。如果实现该目标对个人来说很有价值，个人的积极性就高（P385-386）　<span class="quiz-src">自编</span></p></details><p><a id="q16" class="quiz-anchor"></a></p><p><strong>16.</strong> 某公司任命小王为某信息系统开发项目的项目经理。小王组建的团队经过一段时间的磨合，成员之间相互熟悉和了解，矛盾基本解决，项目经理能够得到团队的认可。由于项目进度落后，小王又向公司提出申请，项目组增加了2名新成员。此时项目团队处于（ ）。</p><ul><li>A．震荡阶段</li><li>B．发挥阶段</li><li>C．形成阶段</li><li>D．规范阶段</li></ul><details class="quiz" data-q="16" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：阶段 解释说明形成阶段 一个个的个体转变为团队成员。团队往往对未来有美好的期待震荡阶段 个体之间开始争执，互相指责，并且开始怀疑项目经理的能力（P382-383）　<span class="quiz-src">2017 年上半年高项</span></p></details><p><a id="q17" class="quiz-anchor"></a></p><p><strong>17.</strong> 韩兹伯格的双因素激励理论中的激励因素类似于马斯洛的需求层次理论中的“（ ）</p><ul><li>A．安全和自我实现</li><li>B．尊重和自我实现</li><li>C．安全和社会认可</li><li>D．社会认可和尊重</li></ul><details class="quiz" data-q="17" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：激励因素：这些因素是与员工的工作本身或工作内容有关的，是高层次的需要，包括成就、承认、工作本身、责任、发展机公等。对应的是马斯洛需求层次的受尊重和自我实现（P383-385）　<span class="quiz-src">2017 年上半年高项</span></p></details><p><a id="q18" class="quiz-anchor"></a></p><p><strong>18.</strong> 项目经理的权力有多种来源，其中（ ）是由于他人对你的认可和敬佩从而愿意模仿和服从你以及希望自己成为你那样的人而产生的，这是一种人格魅力。</p><ul><li>A．职位权力</li><li>B．奖励权力</li><li>C．专家权力</li><li>D．参照权力</li></ul><details class="quiz" data-q="18" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理的5种权力来源权力类型 解释说明职位权力 来源于管理者在组织中的职位和职权、惩罚权力 使用降职、扣薪、惩罚、批评、威胁等负面手段的能力，应谨慎使用（P381-382）　<span class="quiz-src">2017 年下半年高项</span></p></details><p><a id="q19" class="quiz-anchor"></a></p><p><strong>19.</strong> 一般来说，团队发展会经历5个阶段。 “团队成员之间相互依靠，平稳高效地解决问题，团队成员的集体荣誉感非常强”是（ ）的主要特征。</p><ul><li>A．形成阶段</li><li>B．震荡阶段</li><li>C．规范阶段</li><li>D．发挥阶段</li></ul><details class="quiz" data-q="19" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：阶段 解释说明形成阶段 个个的个体转变为团队成员。团队往往对未来有美好的期待震荡阶段 个体之间开始争执，互相指责，并且开始怀疑项目经理的能力（P382-383）　<span class="quiz-src">2017 年下半年高项</span></p></details><p><a id="q20" class="quiz-anchor"></a></p><p><strong>20.</strong> （ ）是通过考察人们的努力行为与其所获得的最终奖酬之间的因果关系来说明激励过程，并以选择合适的行为达到最终的奖酬目标的理论。</p><ul><li>A．马斯洛需求层次理论</li><li>B．赫茨伯格双因素理论</li><li>C．X理论与Y理论</li><li>D．期望理论</li></ul><details class="quiz" data-q="20" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：期望理论认为，一个目标对人的激励程度受2个因素影响：目标效价：指实现该目标对个人有多大价值的主观判断。如果实现该目标对个人来说很有价值，个人的积极性就高；反之，积极性就低（P385-386）　<span class="quiz-src">2017 年下半年高项</span></p></details><p><a id="q21" class="quiz-anchor"></a></p><p><strong>21.</strong> 某项目团队每周组织羽毛球活动，根据马斯洛需求层次理论，该活动满足了项目成员（ ）的需求。</p><ul><li>A．生理</li><li>B．受尊重</li><li>C．社会交往</li><li>D．自我实现</li></ul><details class="quiz" data-q="21" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：社会交往的需求：包括对友谊、爱情以及隶属关系的需求。当生理需求和安全需求得到满足后，社交需求就会凸显，进而产生激励作用（P383-384）　<span class="quiz-src">2018 年上半年高项</span></p></details><p><a id="q22" class="quiz-anchor"></a></p><p><strong>22.</strong> 关于领导者和管理者的描述，正确的是（ ）。</p><ul><li>A．管理者的工作主要是确定方向、统一思想、激励和鼓舞</li><li>B．领导者负责某件具体事情的管理或实现某个具体目标</li><li>C．管理者设定目标，领导者率众实现目标</li><li>D．项目经理具有领导者和管理者的双重身份</li></ul><details class="quiz" data-q="22" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理具有领导者和管理者的双重身份。对项目经理面言，管理能力和领导能力二者均不可或缺。对于大型复杂项目，领导能力尤为重要（P381）　<span class="quiz-src">2019 年上半年高项</span></p></details><p><a id="q23" class="quiz-anchor"></a></p><p><strong>23.</strong> 关于团队建设和管理的描述，不正确的是（ ）。</p><ul><li>A．在团队发展的5个阶段中，震荡阶段之后是规范阶段</li><li>B．团队发展不一定按5个阶段顺序进行，可能会跳过某个阶段</li><li>C．项目经理注重运用奖励权力和惩罚权力，尽量避免使用专家权力</li><li>D．成功的冲突管理可以提高生产力，改进工作关系</li></ul><details class="quiz" data-q="23" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：对于双重汇报关系和非直接江报关系人员的管理，项目经理更注重运用奖励权力、专家权力和参照权力，尽量避免使用惩罚权力（P382）　<span class="quiz-src">2019 年上半年高项</span></p></details><p><a id="q24" class="quiz-anchor"></a></p><p><strong>24.</strong> 在马斯洛需求层次理论中，位于金字塔结构第3层的是（ ）需求。</p><ul><li>A．安全</li><li>B．社会交往</li><li>C．受尊重</li><li>D．自我实现</li></ul><details class="quiz" data-q="24" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：高5.白我实现的需求4受尊重的需求3.社会交往的需求2安全求生理求注：已经满足的需求就不再是激励因素。图13-1 马斯洛的需求层次理论（P383-384）　<span class="quiz-src">2019 年上半年高项</span></p></details><p><a id="q25" class="quiz-anchor"></a></p><p><strong>25.</strong> 领导者的工作主要涉及（ ）。</p><ul><li>A．确定方向、统一思想、实现目标</li><li>B．召集人员、分配任务、激励和鼓舞</li><li>C．召集人员、分配任务、实现目标</li><li>D．确定方向、统一思想、激励和鼓舞</li></ul><details class="quiz" data-q="25" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：领导者(Leader)的工作主要涉及3个方面。①确定方向：为团队设定目标，描绘愿景，制定战略；②统二思想：协调人员，团结尽可能多的力量来实现愿景和项目目标；③激励和鼓蛙：在向项目目标努力的过程中不可避免地要遇到艰难险阻，领导者要激励和鼓舞大家克服困难奋勇前进（P381）　<span class="quiz-src">2019 年下半年高项</span></p></details><p><a id="q26" class="quiz-anchor"></a></p><p><strong>26.</strong> 关于管理者和领导者的描述，不正确的是（ ）。</p><ul><li>A．领导者的主要工作是确定方向、统一思想、激励和鼓舞</li><li>B．管理者负责某件事情的管理或实现某个目标</li><li>C．领导者设定目标，管理者率众实现目标</li><li>D．项目经理的身份是管理者而非领导者</li></ul><details class="quiz" data-q="26" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理具有领导者和管理者的双重身份。对项目经理而言，管理能力和领导能力二者均不可或缺。对于大型复杂项目，领导能力尤为重要（P381）　<span class="quiz-src">2020 年下半年高项</span></p></details><p><a id="q27" class="quiz-anchor"></a></p><p><strong>27.</strong> 在团队发展的5个阶段中，（ ）的特征是：团队成员开始协同工作，并调整各自的工作习惯和行为来支持团队，团队成员开始相互信任，项目经理能够得到团队的认可。</p><ul><li>A．形成阶段</li><li>B．震荡阶段</li><li>C．发挥阶段</li><li>D．规范阶段</li></ul><details class="quiz" data-q="27" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：规范阶段。经过一定时间磨合，团队成员开始协回工作，并调整各自的工作习惯和行为来支持团队，团队成员开始相互信任，项目经理能得到团队的认可（P383）　<span class="quiz-src">2020 年下半年高项</span></p></details><p><a id="q28" class="quiz-anchor"></a></p><p><strong>28.</strong> 关于资源管理的描述，不正确的是（ ）。</p><ul><li>A．项目经理具有领导者和管理者的双重身份</li><li>B．冲突不一定是有害的，“一团和气”不一定是高效的集体</li><li>C．马斯洛需求层次理论中，受尊重是第三层的需求</li><li>D．在团队建设的五个阶段中，可以跳过某些阶段</li></ul><details class="quiz" data-q="28" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：马斯洛需求层次理论中，受尊重是第四层的需求（P383-384）　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q29" class="quiz-anchor"></a></p><p><strong>29.</strong> 近期，国家多个部委发布相关文件，其中“督促平台及第三方合作单位为建立劳动关系的外卖送餐员参加社会保险，支持其他外卖送餐员参加社会保险”。本条信息按照马斯洛的需求层次理论，属于（ ）的需求。</p><ul><li>A．生理</li><li>B．安全</li><li>C．社会交往</li><li>D．受尊重</li></ul><details class="quiz" data-q="29" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：安全需求：包括对人身安全、生活稳定、不致失业以及免灌痛苦、威胁或疾病等的需求。和生理需求一样，在安全需求没有得到满足之前，人们一般不道求更高层的需求（P384）　<span class="quiz-src">2021 年下半年高项</span></p></details><p><a id="q30" class="quiz-anchor"></a></p><p><strong>30.</strong> （ ）是有效领导力的关键要素。</p><ul><li>A．尊重和信任</li><li>B．畏惧和顺从</li><li>C．独立和创新</li><li>D．果断和勇敢</li></ul><details class="quiz" data-q="30" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：领导力是让一个群体为了一个共同的目标而努力的能力。尊重和信任，面非畏惧和顺从，是有效领导力的关键要素。领导力是一种影响力，是对人们施加影响，从而使人们心甘情愿地为实现组织的目标而努力的艺术过程（P381）　<span class="quiz-src">2022 年下半年高项</span></p></details><p><a id="q31" class="quiz-anchor"></a></p><p><strong>31.</strong> 根据赫茨伯格双因素理论，属于保健因素的是（ ）。</p><ul><li>A．工资薪水</li><li>B．升职机会</li><li>C．领导表扬</li><li>D．先进激励</li></ul><details class="quiz" data-q="31" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：保健因素：这些因素是与工作环境或条件有关的，包括工作环境、工资薪水、公司政篮、个人生活、管理监督、人际关系等。激励因素：这些因素是与员工的工作本身或工作内容有关的，是高层次的需要，包括成就、承认、工作本身、责任、发展机会等（P384）　<span class="quiz-src">2022 年下半年高项</span></p></details><p><a id="q32" class="quiz-anchor"></a></p><p><strong>32.</strong> 关于团队管理的描述，不正确的是（ ）。</p><ul><li>A．滥用惩罚权力可能会导致项目失败，应谨慎使用</li><li>B．在赫茨伯格双因素理论中，保健因素的满足可以消除不满，激励因素的满足可以产生满意感</li><li>C．奖励权力来自于组织的授权，参照权力来自于管理者自身</li><li>D．X理论可以激发员工主动性，Y理论注重加强管理与惩罚</li></ul><details class="quiz" data-q="32" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：X理论和Y理论的选择决定管理者处理员工关系的方式。这两个理论各有自已的长处和不足用X理论可以加强管理，但项目团队成员通常是比较被动地工作（P385）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q33" class="quiz-anchor"></a></p><p><strong>33.</strong> （ ）如果得不到满足就会影响员工的精神，导致高缺勤率、低生产率、对工作不满及情绪低落，给员工更多的空间让他负责，让他成为智囊团，参与决策，参与组织的管理会议等，是满足员工（ ）</p><ul><li>A．社会交往的需求、受尊重的需求</li><li>B．社会交往的需求、自我实现的需求</li><li>C．自我实现的需求、社会交往的需求</li><li>D．自我实现的需求、受尊重的需求</li></ul><details class="quiz" data-q="33" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：社会交往的需求；包括对友谊、爱情以及隶属关系的需求。当生理需求和安全需求得到满足后，社交需求就会凸显，进而产生激励作用（P384）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q34" class="quiz-anchor"></a></p><p><strong>34.</strong> 关于项目经理的权力，以下（ ）属于来自于组织授权的权力。“①参照权力；②奖励权力；③专家权力；④职位权力；⑤任免权力</p><ul><li>A．①④</li><li>B．②④</li><li>C．③⑤</li><li>D．①②</li></ul><details class="quiz" data-q="34" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：来自于组织授权的权力：包括职位权力、惩罚权力、奖励权力。来自于管理者自身的权力：包括专家权力、参照权力（P381-382）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q35" class="quiz-anchor"></a></p><p><strong>35.</strong> 以下不属于资源管理方法的是（ ）。</p><ul><li>A．精益管理</li><li>B．约束理论</li><li>C．JIT</li><li>D．六西格玛</li></ul><details class="quiz" data-q="35" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：资源管理方法。过去几年，由于关键资源稀缺，在某些行业中出现了很多新的方法，比如植益管理、准时制(T)生产、Kaizen（持续改盖）、全员生产维护(TPM)、约束理论等项目经理应确定组织是否采用了一种或多种资源管理工具，从而对项目做出相应的调整（P386）　<span class="quiz-src">自编</span></p></details><p><a id="q36" class="quiz-anchor"></a></p><p><strong>36.</strong> 虚拟团队管理面临的挑战主要在于（ ）。</p><ul><li>A．激</li><li>B．文化差异</li><li>C．沟通</li><li>D．工作不好监督</li></ul><details class="quiz" data-q="36" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：虚拟团队管理面临的挑战主要在于沟通，包括团队成员可能产生孤立感、团队成员之间难以分享知识和经验、难以跟进进度和生产率，以及可能存在时区和文化差异等问题（P386-387）　<span class="quiz-src">自编</span></p></details><p><a id="q37" class="quiz-anchor"></a></p><p><strong>37.</strong> 项目经理蜗牛负责某项目管理，考虑到项目人力资源紧张，就与三个在校学生签订了兼职劳务合同，并允许这三名在校学生可以利用互联网进行办公，同时规定每周三上午这些学生必须参与团队的工作会议。以下针对上述情况的观点中，正确的是（ ）。</p><ul><li>A．三名学生不属于项目团队成员</li><li>B．项目经理小王组建了虚拟项目团队</li><li>C．三名学生不可以参加项目团队会议</li><li>D．项目经理小王利用了谈判技术来组建团队</li></ul><details class="quiz" data-q="37" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「项目经理小王组建了虚拟项目团队」，原解析未给课本依据　<span class="quiz-src">2016 年上半年高项</span></p></details><p><a id="q38" class="quiz-anchor"></a></p><p><strong>38.</strong> 下列过程中不属于项目资源管理的是（ ）。</p><ul><li>A．规划资源管理</li><li>B．估算活动资源</li><li>C．估算活动持续时间</li><li>D．获取资源</li></ul><details class="quiz" data-q="38" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：C属于进度管理的过程。项目资源管理过程包括：●规划资源管理●估算活动资源●获取资源●建设团队●管理团队控制资源（P387-388）　<span class="quiz-src">自编</span></p></details><p><a id="q39" class="quiz-anchor"></a></p><p><strong>39.</strong> 由于每个项目都是独特的，项目经理可以根据需要对项目资源管理过程进行裁剪。裁剪时考虑的因素不包括（ ）。</p><ul><li>A．物理位置</li><li>B．团队管理</li><li>C．沟通技术</li><li>D．生命周期方法</li></ul><details class="quiz" data-q="39" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：裁剪时应考虑的因素包括：多元化、物理位置、行业特定资源、团队成员的获得、团队管理生命周期方法（P388）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q40" class="quiz-anchor"></a></p><p><strong>40.</strong> 以下关于资源管理的说法不正确的是（ ）</p><ul><li>A．协作型团队可以促进不同工作活动的快速整合、改善沟通、增加知识分享，同时可以灵活地分配工作。</li><li>B．对于易变性高的项目，更适合采用虚拟团队的方式。</li><li>C．在协作型环境中，快速供应协议和精益方法对控制成本和实现进度非常重要。</li><li>D．对于易变性高的项目，对实物和人力资源规划具有较高的不可预测性。</li></ul><details class="quiz" data-q="40" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：388。对于易变性高的项目，更适合采用能够最大限度地集中和协作的团队结构形式　<span class="quiz-src">自编</span></p></details><p><a id="q41" class="quiz-anchor"></a></p><p><strong>41.</strong> 使用项目资源、做出决策、签字批准、验收可交付成果并影响他人开展项目工作的权力，称之为（ ）。</p><ul><li>A．角色</li><li>B．职责</li><li>C．职权</li><li>D．能力</li></ul><details class="quiz" data-q="41" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：职权是指使用项目资源、做出决策、签字批准、验收可交付成果并影响他人开展项目工作的权力（P392）　<span class="quiz-src">教材第 13 章章节习题</span></p></details><p><a id="q42" class="quiz-anchor"></a></p><p><strong>42.</strong> 下面的过程中，仅开展一次或仅在项目的预定义时开展的过程是（ ）。</p><ul><li>A．规划资源管理</li><li>B．估算活动资源</li><li>C．获取资源</li><li>D．控制资源</li></ul><details class="quiz" data-q="42" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：1、规划资源管理：仅开展一次或仅在项目的预定义时开展。2、估算活动资源：需要在整个项目期间定期开展，3、获取资源：需要在整个项目期间定期开展（P389）　<span class="quiz-src">自编</span></p></details><p><a id="q43" class="quiz-anchor"></a></p><p><strong>43.</strong> 规划资源管理时需要考虑的依据是（ ）。</p><ul><li>A．团队章程</li><li>B．资源管理计划</li><li>C．项目章程</li><li>D．项目团队派工单</li></ul><details class="quiz" data-q="43" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：A不正确。团队章程是规划资源管理的输出。B不正确。资源管理计划是规划资源管理的输出。D不正确。项目团队派工单是获取资源的输出（P389-390）　<span class="quiz-src">自编</span></p></details><p><a id="q44" class="quiz-anchor"></a></p><p><strong>44.</strong> 在规划资源管理的数据表现技术中常见的层级型表现形式不包括（ ）。</p><ul><li>A．工作分解结构</li><li>B．组织分解结构</li><li>C．资源分解结构</li><li>D．RACI矩阵</li></ul><details class="quiz" data-q="44" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：RACI矩阵属于矩阵型。层级型：可采用传统的组织结构图，自上而下地显示各种职位及其相互关系：●工作分解结构(WBS):有助于明确高层级的职责（P390-391）　<span class="quiz-src">自编</span></p></details><p><a id="q45" class="quiz-anchor"></a></p><p><strong>45.</strong> 关于规划资源管理工具和技术的相关描述，不正确的是（ ）</p><ul><li>A．层级型数据表现技术包括工作分解结构、组织分解结构和资源分解结构</li><li>B．组织分解结构按照组织现有部门排列，每个部门下列出项目活动或工作包</li><li>C．RAM矩阵可确保任何一项任务都有多人负责，从而避免单人负责的风险</li><li>D．如果需要详细描述团队成员的职责，可采用文本型工具</li></ul><details class="quiz" data-q="45" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：RAM可确保任何一项任务都只有一个人负责，从而避免职权不清，并非多人负责。层级型数据表现技术包括工作分解结构、组织分解结构和资源分解结构；组织分解结构按照组织现有的部门、单元或团队排列，并在每个部门下列出项目活动或工作包；文本型可用于详细描述团队成员的职责，三者描述均正确（P390-391）　<span class="quiz-src">自编</span></p></details><p><a id="q46" class="quiz-anchor"></a></p><p><strong>46.</strong> （ ）最直观地反映了团队成员个人与其承担的工作之间的联系。</p><ul><li>A．工作分解结构I</li><li>B．组织分解结构</li><li>C．资源分解结构</li><li>D．责任分配矩阵</li></ul><details class="quiz" data-q="46" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：距阵型图表的一个例子是职责分配矩阵(RAM)，它显示了分配给每个工作包的项目资源，用于说明工作包或活动与项目团队成员之间的关系（P391）　<span class="quiz-src">自编</span></p></details><p><a id="q47" class="quiz-anchor"></a></p><p><strong>47.</strong> 关于责任分配矩阵(RAM)的描述，不正确的是（ ）。</p><ul><li>A．大型项目中，RAM可分为多个层</li><li>B．针对具体的一项活动可分配多个成员，每个成员承担不同职责</li><li>C．RAM中用不同的字母表示不同的职责</li><li>D．RAM中每项活动中可以有一个以上成员对任务负责</li></ul><details class="quiz" data-q="47" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：矩阵型图表能反映与每个人相关的所有活动，以及与每项活动相关的所有人员，它也可确保任何一项任务都只有一个人负责，从而避免职权不清（P391）　<span class="quiz-src">自编</span></p></details><p><a id="q48" class="quiz-anchor"></a></p><p><strong>48.</strong> （ ）按资源类别和类型，对团队和实物资源的层级列表，用于规划、管理和控制项目工作，每向下一个层级代表对资源的更详细描述，直到信息细到可以与工作分解结构(WBS)相结合</p><ul><li>A．工作分解结构</li><li>B．组织分解结构</li><li>C．资源分解结构</li><li>D．责任分配矩阵</li></ul><details class="quiz" data-q="48" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：资源分解结构：按资源类别和类型，对团队和实物资源的层级列表，用于规划、管理和控制项目工作，每向下一个层级代表对资源的更详细描述，直到信息细到可以与工作分解结构(WBS)相结合（P391）　<span class="quiz-src">自编</span></p></details><p><a id="q49" class="quiz-anchor"></a></p><p><strong>49.</strong> （ ）按照组织现有的部门、单元或团队排列，并在每个部门下列出项目活动或工作包</p><ul><li>A．工作分解结构</li><li>B．组织分解结构</li><li>C．资源分解结构</li><li>D．责任分配矩阵</li></ul><details class="quiz" data-q="49" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：组织分解结构(OBS):按照组织现有的部门、单元或团队排列，并在每个部门下列出项目活动或工作包（P391）　<span class="quiz-src">自编</span></p></details><p><a id="q50" class="quiz-anchor"></a></p><p><strong>50.</strong> （ ）会直接影响项目的组织结构。</p><ul><li>A．组织分解结构</li><li>B．组织的结构和文化</li><li>C．资源分解结构</li><li>D．责任分配矩阵</li></ul><details class="quiz" data-q="50" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：组织的结构和文化会直接影响项目的组织结构（P391）　<span class="quiz-src">自编</span></p></details><p><a id="q51" class="quiz-anchor"></a></p><p><strong>51.</strong> 某大型项目团队由内部员工和外部合作人员组成，项目经理在规划资源管理时，需要明确划分每位成员的角色和职责，避免出现职权不清、多人负责同一任务的问题。最适合当前情况的工具是（ ）。</p><ul><li>A．工作分解结构</li><li>B．RACI矩阵</li><li>C．文本型工具</li><li>D．组织分解结构</li></ul><details class="quiz" data-q="51" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：综上，B最合适（P391）　<span class="quiz-src">自编</span></p></details><p><a id="q52" class="quiz-anchor"></a></p><p><strong>52.</strong> 以下说法不正确的是（ ）。</p><ul><li>A．职责是指为完成项目活动，项目团队成员必须履行的职责和工作</li><li>B．项目组织图可以是正式或非正式的，非常详细或高度概括的。</li><li>C．如果发现成员能力与职责不匹配，可以给其培训。</li><li>D．下列事项都需要由具有明确职权的人来做决策：质量验收标准，质量控制，集成测试等</li></ul><details class="quiz" data-q="52" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：下列事项都需要由具有明确职权的人来做决策：选择活动的实施方法、质量验收标准，以及如何应对项目偏差等（P392）　<span class="quiz-src">自编</span></p></details><p><a id="q53" class="quiz-anchor"></a></p><p><strong>53.</strong> 团队章程不包括（ ）。</p><ul><li>A．团队价值观</li><li>B．沟通指南</li><li>C．冲突处理过程</li><li>D．团队人员分工</li></ul><details class="quiz" data-q="53" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：团队章程包括：团队价值观、沟通指南、决策标准和过程、冲突处理过程、公议指南和团队共识（P392）　<span class="quiz-src">自编</span></p></details><p><a id="q54" class="quiz-anchor"></a></p><p><strong>54.</strong> 以下说法不正确的是（ ）。</p><ul><li>A．团队章程是为团队创建团队价值观、共识和工作指南的文件</li><li>B．团队章程对项目团队成员的可接受行为确定了明确的期望</li><li>C．团队章程由项目经理制订</li><li>D．可定期审查和更新团队章程，确保团队成员始终了解团队基本规则，并指导新成员融入团队</li></ul><details class="quiz" data-q="54" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：由团队制定或参与制定的团队章程可发握最佳效果，所有项目团队成员都分担责任，确保遵守团队章程中规定的规则（P392）　<span class="quiz-src">自编</span></p></details><p><a id="q55" class="quiz-anchor"></a></p><p><strong>55.</strong> （ ）不属于规划资源管理的输出。</p><ul><li>A．资源管理计划</li><li>B．团队章程</li><li>C．干系人登记册</li><li>D．风险登记册更新</li></ul><details class="quiz" data-q="55" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：干系人登记册是规划资源管理的输入。规划资源管理的输出包括：1资源管理计划（识别资源、获取资源、角色与职责、项目组织图、项目团队资源管理、培训、团队建设、资源控制、认可计划）;2.团队章程；3.项目文件（更新）（假设日志、风险登记册）;（P392-393）　<span class="quiz-src">自编</span></p></details><p><a id="q56" class="quiz-anchor"></a></p><p><strong>56.</strong> 关于资源日历描述不正确的是（ ）。</p><ul><li>A．明确了项目团队成员任务分配和职责明确</li><li>B．资源日历规定了在项目期间确定的团队和实物资源何时可用、可用多久</li><li>C．资源日历识别了每种具体资源可用时的工作日、班次、正常营业的上下班时间、周末和公共假期</li><li>D．资源日历需要在整个项目过程中渐进明细和更新</li></ul><details class="quiz" data-q="56" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：资源日历：识别了每种具体资源可用时的工作且、班次、正常营业的上下班时间、周末和公共假期。在规划活动期间，潜在的可用资源信息（如团队资源、设备和材料）用于估算资源可用性（P391）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q57" class="quiz-anchor"></a></p><p><strong>57.</strong> 规划资源管理的说法中，不正确的是（ ）。</p><ul><li>A．规划资源管理的作用是根据项目类型和复杂程度确定适用于项目资源的管理方法和程度</li><li>B．资源规划用于识别和确定一种方法，以确保有足够的资源能够成功完成项目</li><li>C．有效的资源规划还需要考虑稀缺资源的可用性和竞争方面的问题，并编制相应的计划。</li><li>D．团队章程内容包括团队价值观、冲突处理、角色与职责和项目组织图</li></ul><details class="quiz" data-q="57" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：团队章程是为团队创建团队价值观、共识和工作指南的文件。团队章程包括：●团队价值观：●沟通指南；●决策标准和过程；●冲突处理过程；●会议指南；●团队共识（P392）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q58" class="quiz-anchor"></a></p><p><strong>58.</strong> 某项目 RACI 矩阵如下图所示，以下选项正确的是（ ）。原题附图（略）：RACI 矩阵的行为创建章程、收集需求、制定测试计划、整理资料，列为甲、乙、丙、丁、戊，格内标注 R／A／C／I。</p><ul><li>A．创建章程由甲负责</li><li>B．所有活动都不需要戊提供建议</li><li>C．整理资料由乙咨询</li><li>D．收集需求由丁执行</li></ul><details class="quiz" data-q="58" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：R执行；A负责；C咨询；I知慎（P391）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q59" class="quiz-anchor"></a></p><p><strong>59.</strong> 项目经理卧刘在规划资源管理时编制了一个矩阵图表如下所示，这个表格描述的是团队成员的任务分配和（ ）。人员RACI矩阵王五活动 张三 李四 赵六 刘七RA I I创建章程A R C C收集需求A R R C提交变更请求A C R制订测试计划</p><ul><li>A．职级职位</li><li>B．完成情况</li><li>C．优先级</li><li>D．角色职责</li></ul><details class="quiz" data-q="59" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：矩阵型展示项目资源在各个工作包中的任务分配。矩阵型图表的一个例子是职责分配矩阵(RAM)，它显示了分配给每个工作包的项目资源，用于说明工作包或活动与项目团队成员之间的关系（P391）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q60" class="quiz-anchor"></a></p><p><strong>60.</strong> 规划资源管理的输出是（ ）。</p><ul><li>A．团队章程、团队管理计划</li><li>B．团队章程、资源分解结构</li><li>C．资源管理计划、资源日历</li><li>D．资源管理计划、资源分解结构</li></ul><details class="quiz" data-q="60" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：作为项目管理计划的一部分，资源管理计划提供了关于如何分类、分配管理和释放项目资源的指南。资源管理计划可以根据项目的具体情况分为团队管理计划和实物资源管理计划（P392）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q61" class="quiz-anchor"></a></p><p><strong>61.</strong> （ ）不属于团队章程的内容。</p><ul><li>A．团队价值观</li><li>B．资源日历</li><li>C．沟通指南</li><li>D．冲突处理过程</li></ul><details class="quiz" data-q="61" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：团队章程包括：团队价值观、沟通指南、决策标准和过程、冲突处理过程、会议指南和团队共识（P392）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q62" class="quiz-anchor"></a></p><p><strong>62.</strong> （ ）不是影响资源规划的事业环境因素。</p><ul><li>A．组织文化和结构</li><li>B．设施和资源的物理分布</li><li>C．现有资源的能力和可用性</li><li>D．物质资源管理政策和程序</li></ul><details class="quiz" data-q="62" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：事业环境因素：能够影响规划资源管理过程的事业环境因素包括：组组文化和结构；设施和资源的物理分布；现有资源的能力和可用性；市场条件等组织过程资产：能够影响规划资源管理过程的组织过程资产包括：人力资源政策和程序；物质资源管理政策和程序；安全政策；安保政策；资源管理计划模板；类似项目的历史信息等（P390）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q63" class="quiz-anchor"></a></p><p><strong>63.</strong> 矩阵型图表的一个例子是职责分配矩阵(RAM)，它显示了分配给每个工作包的项目资源，用于说明工作包或活动与项目团队成员之间的关系。RAM的一个例子是RACI矩阵。其中RAC中的C指的是（ ）。</p><ul><li>A．知情</li><li>B．咨询</li><li>C．负责</li><li>D．执行</li></ul><details class="quiz" data-q="63" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：R执行；A负责；C咨询；I知情（P391）　<span class="quiz-src">2023 年下半年高项第 3 批</span></p></details><p><a id="q64" class="quiz-anchor"></a></p><p><strong>64.</strong> （ ）用于展示团队成员的职责分配和角色。</p><ul><li>A．干系人参与度评估矩阵</li><li>B．责任分配矩阵</li><li>C．组织分解结构</li><li>D．工作分解结构</li></ul><details class="quiz" data-q="64" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：组织分解结构(OBS);按照组织现有的部门、单元或团队排列，并在每个部门下列出项目活动或工作包。资源分解结构：按资源类别和类型，对团队和实物资源的层级列表，用于规划、管理和控制项目工作，每向下一个层级代表对资源的更详细描述，直到信息细到可以与工作分解结构(WBS相结合（P391）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q65" class="quiz-anchor"></a></p><p><strong>65.</strong> 关于规划资源管理过程的数据表现技术的描述，正确的是（ ）。①矩阵型数据表现技术可用于表示高层次角色②资源分解结构用于规划、管理和控制项目工作，每向下一个层级代表对资源的更详细描述③运营部门只需找到其所在的组织结构分解(OBS)位置，就能看到自己的全部项目职责“④层次型表能反映与每个人相关的所有活动，以及与每项活动相关的所有人员⑤如果需要详细描述团队成员的职责，就可以采用文本型</p><ul><li>A．②③⑤</li><li>B．①③④</li><li>C．②③④</li><li>D．①③⑤</li></ul><details class="quiz" data-q="65" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：资源分解结构：按资源类别和类型，对团队和实物资源的层级列表，用于规划、管理和控制项目工作，每向下一个层级代表对资源的更详细描述，直到信息细到可以与工作分解结构(WBS)相结合（P391）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q66" class="quiz-anchor"></a></p><p><strong>66.</strong> 与资源管理计划相关的描述正确的是（ ）。</p><ul><li>A．资源管理计划包含会议指南，用于规范项目团队沟通与决策流程</li><li>B．资源管理计划包含团队价值观，用于引导团队成员的行为准则与协作方式</li><li>C．资源管理计划包含角色与职责，其中能力是指为完成项目活动，项目团队成员须具备的技能和才干</li><li>D．资源管理计划包含资源控制，主要聚焦于人力资源的绩效考核与激励措施</li></ul><details class="quiz" data-q="66" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：角色与职责：①角色是指在项目中某人承担的职务或分配给某人的职务，如土木工程师、商业分析师和测试协调员。②职权是指使用项目资源、做出决策、签字批淮、验收可交付成果并影响他人开展项目工作的权力　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q67" class="quiz-anchor"></a></p><p><strong>67.</strong> 能够影响“规划资源管理”过程的组织过程资产包括：（ ）。①资源需求；②人力资源政策；③资源分解结构；④物质资源管理程序；⑤安保政策</p><ul><li>A．②④⑤</li><li>B．①②③</li><li>C．②④</li><li>D．①③④</li></ul><details class="quiz" data-q="67" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O。能够影响规划资源管理过程的组织过程资产包括：人力资源政策和程序；物质资源管理政策和程序；安全政策；安保政策；资源管理计划模板；类似项目的历史信息等（P39）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q68" class="quiz-anchor"></a></p><p><strong>68.</strong> 获取资源过程的输出中，（ ）识别了每种具体资源可用时的工作日、班次、正常营业的上下班时间、周末和公共假期。</p><ul><li>A．组织过程资产更新</li><li>B．物质资源分配单</li><li>C．项目团队派工单</li><li>D．资源日历</li></ul><details class="quiz" data-q="68" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：资源日历：识别了每种具体资源可用时的工作且、班次、正常营业的上下班时间、周末和公共假期（P394）　<span class="quiz-src">教材第 13 章章节习题</span></p></details><p><a id="q69" class="quiz-anchor"></a></p><p><strong>69.</strong> 估算活动资源是估算执行项目所需的团队资源，以及材料、设备和用品的类型和数量的过程，其主要作用是（ ）。</p><ul><li>A．在整个项目期间为如何管理项目成本提供指南和方向</li><li>B．确定项目所需的资金</li><li>C．明确完成项目所需的资源种类、数量和特性</li><li>D．在整个项目期间为如何管理和核实质量提供指南和方向</li></ul><details class="quiz" data-q="69" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：估算活动资源是估算执行项目所需的团队资源、设施、设备、材料、用品和其他资源的类型和数量的过程。本过程的主要作用是明确完成项目所盖的资源种类、数量和特性（P393）　<span class="quiz-src">自编</span></p></details><p><a id="q70" class="quiz-anchor"></a></p><p><strong>70.</strong> 估算活动资源时不需要考虑的依据是（ ）。</p><ul><li>A．风险登记册</li><li>B．范围基准</li><li>C．活动清单</li><li>D．估算依据</li></ul><details class="quiz" data-q="70" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：D不正确。估算依据是估算活动资源的输出。估算活动资源的输入包括：1项目管理计划（范围基准、资源管理计划）:2.项目文件（假设日志、风险登记册、活动属性、活动清单、成本估算、资源日历）;3.事业环境因素；4.组织过程资产（P393-394）　<span class="quiz-src">自编</span></p></details><p><a id="q71" class="quiz-anchor"></a></p><p><strong>71.</strong> 关于估算活动资源过程及相关描述，正确的是（ ）。①估算活动资源是估算执行项目所需的团队资源，以及材料、设备和用品的类型和数量的过程②估算活动资源过程仅开展一次，在之后的活动中定期更新“③范围基准是估算活动资源过程的输入，范围决定了对团队和实物资源的需求④资源管理计划定义了识别项目所需不同资源的方法⑤资源日历是估算活动资源的输出，识别了每种具体资源可用时的工作日、班次、正常营业的上下班时间、周末和公共假期。</p><ul><li>A．①②③</li><li>B．①③④</li><li>C．①④5</li><li>D．C34</li></ul><details class="quiz" data-q="71" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：估算活动资源是估算执行项目所需的团队资源，以及材料、设备和用晶的类型和数量的过程。因此①正硫。估算活动资源过程需要在整个项目期间定期开展，并非仅开展一次，因此②错误（P393-394）　<span class="quiz-src">自编</span></p></details><p><a id="q72" class="quiz-anchor"></a></p><p><strong>72.</strong> 关于估算活动资源过程的描述不正确的是（ ）。</p><ul><li>A．范围基准识别了实现项目目标所需的项目和产品范围，而范围决定了对团队和实物资源的需求</li><li>B．活动属性为估算活动清单中每项活动所需的团队和实物资源提供了数据来源</li><li>C．成本估算，资源成本从数量和技能水平方面会影响资源选择</li><li>D．能够影响估算资源过程的组织过程资产包括资源的位置、资源可用性</li></ul><details class="quiz" data-q="72" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：能够影响估算活动资源过程的事业环境因素包括：资源的位置、资源可用性、团队资源的技能、组织文化、发布的估算数据以及市场条件等（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q73" class="quiz-anchor"></a></p><p><strong>73.</strong> 项目经理蜗牛老师在接手项目A时，由于处于项目初期，仅了解了WBS的几个高层级情况这个时候蜗牛老師应该采用哪种方式来估算资源更合适（ ）。</p><ul><li>A．专家判断</li><li>B．自下面上估算</li><li>C．类比估算</li><li>D．参数估算</li></ul><details class="quiz" data-q="73" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：类比估算将以往类似项目的资源相关信息作为估算未来项目的基础。这是一种快速估算方法，适用于项目经理只能识别WBS的儿个高层级的情况（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q74" class="quiz-anchor"></a></p><p><strong>74.</strong> （ ）规定了在项目期间确定的团队和实物资源何时可用、可用多久。</p><ul><li>A．物质资源分配单</li><li>B．项目团队派工单</li><li>C．资源日历</li><li>D．资源需求</li></ul><details class="quiz" data-q="74" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：资源日历规定了在项目期间确定的团队和实物资源何时可用、可用多久（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q75" class="quiz-anchor"></a></p><p><strong>75.</strong> （ ）不是活动资源估算的工具。</p><ul><li>A．专家判断法</li><li>B．类比估算</li><li>C．挣值管理</li><li>D．估算软件</li></ul><details class="quiz" data-q="75" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：挣值管理是测量项目绩效最常用的方法，不是活动资源估算的工具。估算活动资源的工具与技术包括：1专家判断；2.自下而上估算；3类比估算；4.参数估算；5数据分析；6项目管理信息系统；7.会议（P394-395）　<span class="quiz-src">自编</span></p></details><p><a id="q76" class="quiz-anchor"></a></p><p><strong>76.</strong> 项目管理信息系统包括（ ）软件，这些软件有助于规划、组织与管理资源库，以及编制资源估算。</p><ul><li>A．资源管理</li><li>B．CRM系统</li><li>C．采购系统或智能分析</li><li>D．BOM系统</li></ul><details class="quiz" data-q="76" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目管理信息系统可以包括资源管理软件，这些软件有助于规划、组织与管理资源库，以及编制资源估算（P395）　<span class="quiz-src">自编</span></p></details><p><a id="q77" class="quiz-anchor"></a></p><p><strong>77.</strong> （ ）识别了各个工作包中每项活动所需的资源类型和数量。</p><ul><li>A．资源需求</li><li>B．资源分解结构</li><li>C．资源管理计划</li><li>D．估算范围</li></ul><details class="quiz" data-q="77" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：资源需求识别了各个工作包中每项活动所需的资源类型和数量（P395）　<span class="quiz-src">自编</span></p></details><p><a id="q78" class="quiz-anchor"></a></p><p><strong>78.</strong> 资源分析人员在对某项目进行活动资源估算分析时，发现的主要问题是：该项目依赖张工的经验和个人能力，但同时蜗张牛工老还师在其它项目中担任重要角色。为了保证项目资源的使用不发生冲突，资源分析人员在进行资源估算时应提交（ ）</p><ul><li>A．专家评审意见</li><li>B．活动属性(</li><li>C．资源类比估算清单</li><li>D．资源日历</li></ul><details class="quiz" data-q="78" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「资源日历」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q79" class="quiz-anchor"></a></p><p><strong>79.</strong> 项目经理蜗牛老师在对项目A的某一子系统进行估算时，发现该子系统一共包含12个功能点，这些功能点公司有现成的代码库和估算公式，于是蜗牛老师直接根据公司提供的估算公式输入功能点数进行了估算，请问蜗牛老师采用的是什么估算方法（ ）。</p><ul><li>A．专家判断</li><li>B．自下而上估算</li><li>C．类比估算</li><li>D．参数估算</li></ul><details class="quiz" data-q="79" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「参数估算」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q80" class="quiz-anchor"></a></p><p><strong>80.</strong> 估算活动资源”过程的主要作用是明确完成项目所需资源（ ）、数量和（ ）。</p><ul><li>A．种类、特性</li><li>B．来源、分配</li><li>C．来源、成本</li><li>D．价格、质量</li></ul><details class="quiz" data-q="80" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：估算活动资源是估算执行项目所需的团队资源、设施、设备、材料、用品和其他资源的类型和数量的过程。本过程的主要作用是明确完成项目所需的资源种类、数量和特性（P393）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q81" class="quiz-anchor"></a></p><p><strong>81.</strong> 资源分解结构属于（ ）过程的输出。</p><ul><li>A．估算活动资源</li><li>B．管理项目知识</li><li>C．规划成本管理</li><li>D．规划资源管理</li></ul><details class="quiz" data-q="81" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：395-396。估算活动资源过程输出：①资源需求；②估算依据；③资源分解结构；④项目文件（更新）（假设日志、活动属性、经验教训登记册）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q82" class="quiz-anchor"></a></p><p><strong>82.</strong> 关于估算活动资源过程的描述不正确的是（ ）。</p><ul><li>A．资源管理计划是估算活动资源过程的输入，定义了识别项目所需不同资源的方法，还定义了量化各活动所需的方法</li><li>B．资源日历是估算活动资源过程的输出，识别每种具体资源可用时间和时长</li><li>C．资源需求清单详细列出了为完成项目活动所需的各种资源，包括人力资源和物资等</li><li>D．历史信息提供以往项目中资源使用的数据和经验教训</li></ul><details class="quiz" data-q="82" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：资源日历是估算活动资源过程的输入（P393-394）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q83" class="quiz-anchor"></a></p><p><strong>83.</strong> （ ）不是估算活动资源的输出。</p><ul><li>A．估算依据</li><li>B．资源日历</li><li>C．资源雷求</li><li>D．资源分解结构</li></ul><details class="quiz" data-q="83" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：估算活动资源的输出：1资源需求2.估算依据3.资源分解结构4.项目文件更新（假设日志活动属性、经验教训登记册）（P395）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q84" class="quiz-anchor"></a></p><p><strong>84.</strong> 在项目资源管理中，（ ）识别了需要资源的活动，（ ）识别了资源的可用性</p><ul><li>A．活动清单、资源日历</li><li>B．假设日志、资源需求</li><li>C．资源分解结构、资源日历</li><li>D．活动属性、风险登记册</li></ul><details class="quiz" data-q="84" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：活动清单：识别了需要资源的活动，资源日历：识别了每种具体资源可用时的工作日、班次、正常营业的上下班时间、周末和公共假期（P394）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q85" class="quiz-anchor"></a></p><p><strong>85.</strong> 虚拟团队的使用能带来很多好处，不包括（ ）。</p><ul><li>A．减少出差及搬迁费用</li><li>B．减少信息分享带来的安全风险</li><li>C．利用技术来营造在线团队环境</li><li>D．拉近团队成员与供应商、客户或其他重要干系人的距离</li></ul><details class="quiz" data-q="85" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：虚拟团队模式使人们有可能：①在组织内部地处不同地理位置的员工之间组建团队；②为项目团队增加特殊技能，即使相应的专家不在同一地理区城；③将在家办公的员工纳入团队；④在工作班次、工作小时或工作日不同的员工之间组建团队：⑥将行动不便者或残疾人纳入团队：⑥执行那些原本公因差旅费用过高面被捌置或取消的项目；⑦节省员工所需的办公室和所有实物设备的开支等（P399）　<span class="quiz-src">教材第 13 章章节习题</span></p></details><p><a id="q86" class="quiz-anchor"></a></p><p><strong>86.</strong> （ ）是获取项目所需的团队资源、设施、设备、材料、用品和其他资源的过程</p><ul><li>A．获取资源</li><li>B．管理资源</li><li>C．控制资源</li><li>D．规划资源</li></ul><details class="quiz" data-q="86" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：396。获取资源是获取项目所需的团队资源、设施、设备、材料、用晶和其他资源的过程　<span class="quiz-src">自编</span></p></details><p><a id="q87" class="quiz-anchor"></a></p><p><strong>87.</strong> （ ）的主要作用是概述和指导资源的选择，并将其分配给相应的活动。</p><ul><li>A．获取资源</li><li>B．管理资源</li><li>C．控制资源</li><li>D．规划资源</li></ul><details class="quiz" data-q="87" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：获取资源是获取项目所需的团队资源、设施、设备、材料、用品和其他资源的过程。本过程的主要作用：①概述和指导资源的选择；②将选择的资源分配给相应的活动（P396）　<span class="quiz-src">自编</span></p></details><p><a id="q88" class="quiz-anchor"></a></p><p><strong>88.</strong> 项目所需资源可能来自项目执行组织的内部或外部。内部资源由职能经理或资源经理负责获取，外部资源则通过（ ）获得。</p><ul><li>A．合同管理</li><li>B．建设团队</li><li>C．管理团队</li><li>D．采购过程</li></ul><details class="quiz" data-q="88" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目所需资源可能来自项目执行组织的内部或外部。内部资源由职能经理或资源经理负责获取（分配），外部资源则通过采购过程获得（P396）　<span class="quiz-src">自编</span></p></details><p><a id="q89" class="quiz-anchor"></a></p><p><strong>89.</strong> 关于获取资源的描述，不正确的是（ ）。</p><ul><li>A．项目经理对团队成员的选择具有直接控制权</li><li>B．人力资源不足可能导致项目取消</li><li>C．项目经理应在项目管理计划中说明缺少所需人力资源的后果</li><li>D．在人员分派谈判中，需要项目经理具备较强的影响他人的能力</li></ul><details class="quiz" data-q="89" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：因为集体劳资协议、分包商人员使用、矩阵型项目环境、内外部报告关系或其他原因，项目管理团队有可能没有对资源选择的直接控制权（P396）　<span class="quiz-src">自编</span></p></details><p><a id="q90" class="quiz-anchor"></a></p><p><strong>90.</strong> 在项目资源获取过程中，以下说法正确的是（ ）。</p><ul><li>A．项目经理无需与资源提供方谈判，可直接申请并获取所需团队和实物资源</li><li>B．若无法获得项目所需资源，仅会导致项目进度延误，不会影响项目质量和风险</li><li>C．因经济因素无法获取核心团队资源时，在符合法律和强制性标准的前提下，可使用能力或成本不同的替代资源</li><li>D．当资源或人员能力不足时，只会降低项目效率，不会导致项目被取消</li></ul><details class="quiz" data-q="90" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在获取项目资源过程中应注意如下事项：①项目经理或项目团队应该进行有效谈判，并影响那些能为项目提供所需团队和实物资源的人员；②不能获得项目所盖的资源时，可能公影响项目进度、预算、客户满意度、质量和风险，资源或人员能力不是公隆低项目成功的概率，最坏情况下可能导致项目被取消；③因制约因素（如经济因素或其他项目对资源的占用）面无法获得所需切队资额时，项目经埋或项目团队可能不得不使用地许能力和成本不间的管代…（P396）　<span class="quiz-src">自编</span></p></details><p><a id="q91" class="quiz-anchor"></a></p><p><strong>91.</strong> 获取资源时不需要考虑的依据是（ ）。</p><ul><li>A．资源日历</li><li>B．资源管理计划</li><li>C．成本基准</li><li>D．干系人登记册</li></ul><details class="quiz" data-q="91" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A不正确。资源日历是获取资源的输出。获取资源的输入包括：1项目管理计划（资源管理计划、成本基准、采购管理计划）;2.项目文件（项目进度计划、资源需求、干系人登记册）3.事业环境因素；4.组织过程资产（P397-398）　<span class="quiz-src">自编</span></p></details><p><a id="q92" class="quiz-anchor"></a></p><p><strong>92.</strong> 以下不属于团队资源独有的选择标准的是（ ）。</p><ul><li>A．经验</li><li>B．国际因素</li><li>C．态度</li><li>D．成本</li></ul><details class="quiz" data-q="92" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：资源选择标准：可用性、成本、能力、团队资源独特的：经验、知识、技能、态度、国际因素。实物资源也可能要考虑成本（P398）　<span class="quiz-src">自编</span></p></details><p><a id="q93" class="quiz-anchor"></a></p><p><strong>93.</strong> 在项目资源获取的谈判工作中，以下关于谈判对象与目的说法，正确的是（ ）。</p><ul><li>A．与职能经理谈判的核心目的是争取外部稀缺的特殊实物资源</li><li>B．与外部组织和供应商谈判时，无需关注对方所在地区的相关法律和政策</li><li>C．与执行组织内其他项目管理团队谈判，是为了合理分配稀缺或特殊资源</li><li>D．项目管理团队无需具备影响他人的能力，仅靠正式流程即可完成资源谈判</li></ul><details class="quiz" data-q="93" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：适用于获取资源过程的人际关系与团队技能是谈判。很多项目需要针对所需资源进行谈判项目管理团队需要与下列各方谈判：●职能经理：确保项目在要求的时限内获得最佳资源，直到完成职责（P398）　<span class="quiz-src">自编</span></p></details><p><a id="q94" class="quiz-anchor"></a></p><p><strong>94.</strong> 适用于获取资源过程的决策技术是多标准决策分析，其可使用的选择标准不包括（ ）</p><ul><li>A．国际因素</li><li>B．成本</li><li>C．技能</li><li>D．长相</li></ul><details class="quiz" data-q="94" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：适用于获取资源过程的决策技术是多标准决策分析。选择标准常用于选择项目的实物资源或项目团队。可使用的选择标准包括：可用性、成本、能力、经验、知识、技能、态度、国际因盛（P398）　<span class="quiz-src">自编</span></p></details><p><a id="q95" class="quiz-anchor"></a></p><p><strong>95.</strong> 某公司在投标时就将准备安排到该项目的项目经理给指定了，这个时候该项目经理还在外地某个项目出差，请问这属于（ ）。</p><ul><li>A．虚拟团队</li><li>B．预分派</li><li>C．招募</li><li>D．变更请求</li></ul><details class="quiz" data-q="95" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：预分派指事先确定项目的实物或团队资源，在如下情况时可采用预分派：①在竞标过程中承诺分派特定人员进行项目工作；②项目取决于特定人员的专有技能；③在完成资源管理计划的前期工作之前，制定项目章程过程或其他过程已经指定了某些团队成员的工作（P398）　<span class="quiz-src">自编</span></p></details><p><a id="q96" class="quiz-anchor"></a></p><p><strong>96.</strong> 以下哪种情况不属于预分派（ ）。</p><ul><li>A．在竞标过程中承诺分派特定人员进行项目工作</li><li>B．项目取决于特定人员的专有技能</li><li>C．在完成资源管理计划的前期工作之前，制定项目章程过程或其他过程已经指定了某些团队成员的工作</li><li>D．项目经理让人事部预先招聘2名储备人员</li></ul><details class="quiz" data-q="96" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：预分派指事先确定项目的实物或团队资源，在如下情况时可采用预分派：①在章标过程中承诸分派特定人员进行项目工作；②项目取决于特定人员的专有技能；④在完成资源管理计划的前期工作之前，制定项目章程过程或其他过程已经指定了某些团队成员的工作（P398）　<span class="quiz-src">自编</span></p></details><p><a id="q97" class="quiz-anchor"></a></p><p><strong>97.</strong> 关于资源管理的描述，不正确的是（ ）。</p><ul><li>A．内部资源由职能经理或资源经理负责获取（分配），外部资源则通过采购过程获得</li><li>B．RAM可确保任何一项任务都只有一个人负责</li><li>C．在虚拟团队的环境中，个人工作技能变得尤为重要</li><li>D．集中办公既可以是临时的，也可以贯穿整个项目</li></ul><details class="quiz" data-q="97" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在虚拟团队的环境中，沟通规划变得尤为重要（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q98" class="quiz-anchor"></a></p><p><strong>98.</strong> 关于虚拟团队的描述，不正确的是（ ）。</p><ul><li>A．现代通信技术，如Email、微信等，有助于虚拟团队的沟通和管理</li><li>B．虚拟团队有助于将行动不便，在家办公或有特殊技能的人纳入团队</li><li>C．与实体团队相比，虚拟团队成员之间更容易分享知识和经验</li><li>D．与实体团队相比，在虚拟团队中制定可行的沟通计划更加重要</li></ul><details class="quiz" data-q="98" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在虚拟团队的环境中，沟通规划变得尤为重要。可能需要花更多时间来设定明确的期望、促进沟通、制定冲突解决方法、召集人员参与决策、理解文化差异，以及共享成功喜悦（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q99" class="quiz-anchor"></a></p><p><strong>99.</strong> （ ）记录了团队成员及其在项目中的角色和职责，可包括项目团队名录，还需要把人员姓名插入项目管理计划的其他部分，如项目组织图和进度计划。</p><ul><li>A．组织过程资产更新</li><li>B．物质资源分配单</li><li>C．项目团队派工单</li><li>D．资源日历</li></ul><details class="quiz" data-q="99" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目团队源工单记录了团队成员及其在项目中的角色和职责，可包括项目团队名录，还需要把人员姓名插入项目管理计划的其他部分，如项目组织图和进度计划（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q100" class="quiz-anchor"></a></p><p><strong>100.</strong> 关于虚拟团队的描述，不正确的是（ ）。</p><ul><li>A．在建立虚拟团队时，沟通计划尤为重要</li><li>B．虚拟团队可能会造成团队成员的孤立感</li><li>C．虚拟团队有利于节约差旅成本</li><li>D．虚拟团队有利于知识和经验分享</li></ul><details class="quiz" data-q="100" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：在虚拟团队的环境中，沟通规划变得尤为重要。可能盖要花更多时间来设定明确的期望、促进沟通、制定冲突解决方法、召集人员参与决策、理解文化差异，以及共享成功喜悦（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q101" class="quiz-anchor"></a></p><p><strong>101.</strong> （ ）记录了项目将使用的材料、设备、用品、地点和其他实物资源。</p><ul><li>A．组织过程资产更新</li><li>B．物质资源分配单</li><li>C．项目团队派工单</li><li>D．资源日历</li></ul><details class="quiz" data-q="101" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：物质资源分配单记录了项目将使用的材料、设备、用品、地点和其他实物资源（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q102" class="quiz-anchor"></a></p><p><strong>102.</strong> 以下（ ）不是获取资源过程的输出。</p><ul><li>A．物质资源分配单</li><li>B．项目团队派工单</li><li>C．资源日历</li><li>D．资源需求</li></ul><details class="quiz" data-q="102" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：资源需求是获取资源的输入。获取资源的输出包括：1物质资源分配单；2.项目团队派工单3资源日历：4.变更请求：5项目管理计划（更新）（资源管理计划、成本基准）;6.项目文件（更新）（经验教调登记册、项目进度计划、资源分解结构、资源需求、风险登记册、干系人登记册）;7.事业环境因素（更新）;“8.组织过程资产（更新）（P399-400）　<span class="quiz-src">自编</span></p></details><p><a id="q103" class="quiz-anchor"></a></p><p><strong>103.</strong> 获取资源的主要依据不包括（ ）。</p><ul><li>A．资源需求</li><li>B．项目进度计划</li><li>C．物质资源分配单</li><li>D．干系人登记册</li></ul><details class="quiz" data-q="103" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：获取资源过程的输入为项目管理计划（资源管理计划、采购管理计划成本基准等）、项目文件（项目进度计划、资源需求、干系人登记册）、组织过程资产、事业环境因监（P396）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q104" class="quiz-anchor"></a></p><p><strong>104.</strong> 以下关于资源日历的说法中，正确的是（ ）。</p><ul><li>A．资源日历有工作日和假期</li><li>B．资源日历记录了团队成员及其在项目中的角色和职责</li><li>C．资源日历只包含人力资源不包括实物资源</li><li>D．资源日历记录了项目将使用的材料、设备、用品、地点和其他实物资源</li></ul><details class="quiz" data-q="104" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：资源日历识别了每种具体资源可用时的工作且、班次、正常营业的上下班时间、周末和公共假期。资源日历规定了在项目期间确定的团队和实物资源何时可用和可用多久（P399）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q105" class="quiz-anchor"></a></p><p><strong>105.</strong> 项目团队招募了一名高级网络架构师，为其办理了入职手续，在（ ）中明确了该成员在项目中的角色和职责。</p><ul><li>A．项目章程</li><li>B．项目团队派工单</li><li>C．资源日历</li><li>D．团队章程</li></ul><details class="quiz" data-q="105" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目团队派工单记录了团队成员及其在项目中的角色和职责，可包括项目团队名单，还需要把人员姓名插入项目管理计划的其他部分，如项目组织图和进度计划（P399）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q106" class="quiz-anchor"></a></p><p><strong>106.</strong> （ ）不是虚拟团队的优势。</p><ul><li>A．更好地利用不在同一地理区域的专家的专业技术</li><li>B．提高沟通效率，便于分享知识和经验</li><li>C．将在家办公的员工纳入团队</li><li>D．节约差旅费用和办公场地费用</li></ul><details class="quiz" data-q="106" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：在虚拟团队的环境中，沟通规划变得尤为重要，沟通是虚拟团队的然点不是优势（P399）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q107" class="quiz-anchor"></a></p><p><strong>107.</strong> （ ）是指事先确定项目的实物或团队资源。</p><ul><li>A．预分派</li><li>B．虚拟团队</li><li>C．集中办公</li><li>D．冲突管理</li></ul><details class="quiz" data-q="107" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：预分派是指事先确定项目的实物或团队资源（P398）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q108" class="quiz-anchor"></a></p><p><strong>108.</strong> 在获取资源过程中，（ ）情况下不需要采用预分派。</p><ul><li>A．项目需要采购外部资源</li><li>B．在竞标过程中承诺分派特定人员进行项目工作</li><li>C．在完成资源管理计划的前期工作之前，制定项目章程过程或其他过程已经指定了某些团队成员的工作</li><li>D．项目取决于特定人员的专有技能</li></ul><details class="quiz" data-q="108" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：预分派指事先确定项目的实物或团队资源，在如下情况时可采用预分派：①在竞标过程中承诺分派特定人员进行项目工作；②项目取决于特定人员的专有技能；③在完成资源管理计划的前期工作之前，制定项目章程过程或其他过程已经指定了某些团队成员的工作（P398）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q109" class="quiz-anchor"></a></p><p><strong>109.</strong> 能够影响获取资源过程的事业环境因素不包含（ ）。</p><ul><li>A．项目资源的采购政策</li><li>B．有关团队资源的以往经验</li><li>C．现有组织资源信息</li><li>D．市场条件和地理位置</li></ul><details class="quiz" data-q="109" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：能够影响获取资源过程的事业环境因素有：现有组织资源信息，包括可用性、能力水平，以及有关团队资源和资源成本的以往经验；市场条件；组织结构；地理位置等能够影响获取资源过程的组织过程资产包括：有关项目资源的采购、配置和分配的政策和程序；历史信息和经验教训知识库等（P397）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q110" class="quiz-anchor"></a></p><p><strong>110.</strong> 项目资源管理（ ）过程的输出中，（ ）记录了团队成员及其在项目中的角色和职责；（ ）记录了团队成员工作日、班次、正常营业的上下班时间、周末和公共假期等信息</p><ul><li>A．建设团队、资源分解结构、资源日历</li><li>B．规划资源管理、资源日历、资源分解结构</li><li>C．管理团队、物质资源分配单、项目团队派工单</li><li>D．获取资源、项目团队派工单、资源日历</li></ul><details class="quiz" data-q="110" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目团队派工单记录了团队成员及其在项目中的鱼色和职查，可包括项目团队名录，还需要把人员姓名插入项目管理计划的其他部分，如项目组织图和进度计划资源日历识别了每种具体资源可用时的工作日、班次、正常营业的上下班时间、周末和公共假期（P399）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q111" class="quiz-anchor"></a></p><p><strong>111.</strong> 评价团队有效性的指标，不包括（ ）。</p><ul><li>A．个人技能的改进</li><li>B．团队成员离职率的提升</li><li>C．团队能力的改进</li><li>D．团队凝聚力的加强</li></ul><details class="quiz" data-q="111" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：评价团队有效性的指标可包括：①个人技能的改进，使成员更有效地完成工作任务；②团队能力的改进，从面使团队成员更好地开展工作；③团队成员离职率的降低；④团队凝聚力的加强，从而使团队成员公开分辛信息和经验，并互相帮助来提高项目绩效（P404）　<span class="quiz-src">教材第 13 章章节习题</span></p></details><p><a id="q112" class="quiz-anchor"></a></p><p><strong>112.</strong> （ ）是提高工作能力、促进团队成员互动、改善团队整体氛围，以提高项目绩效的过程。</p><ul><li>A．管理团队</li><li>B．控制团队</li><li>C．获取资源</li><li>D．建设团队</li></ul><details class="quiz" data-q="112" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：建设团队是提高工作能力、促进团队成员互动、改善团队整体氛围，以提高项目绩效的过程（P400）　<span class="quiz-src">自编</span></p></details><p><a id="q113" class="quiz-anchor"></a></p><p><strong>113.</strong> 改进团队协作、增强人际关系技能、激励员工、减少摩擦以及提升整体项目绩效，是（ ）过程的主要作用。</p><ul><li>A．建设团队</li><li>B．管理团队</li><li>C．控制资源</li><li>D．获取资源</li></ul><details class="quiz" data-q="113" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：OO。建设团队的主要作用是：改进团队协作、增强人际关系技能、激励员工、减少摩擦以及握升整体项目绩效（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q114" class="quiz-anchor"></a></p><p><strong>114.</strong> 可实现团队高效运行的行为不包含（ ）。</p><ul><li>A．使用开放与有效的沟通</li><li>B．创造团队建设机遇</li><li>C．建立团队成员间的信任</li><li>D．考核团队绩效并向成员反馈考核结果</li></ul><details class="quiz" data-q="114" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O1。可实现团队的高效运行的行为有：①使用开放与有效的沟通；②创造团队建设机遇；③建立团队成员间的信任；④以建设性方式管理冲突；⑥鼓励合作型的问题解决方法；⑥鼓励合作型的决策方法等（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q115" class="quiz-anchor"></a></p><p><strong>115.</strong> 关于项目经理在全球化、富有文化多样性的项目中的团队管理工作，以下说法正确的是（ ）</p><ul><li>A．为避免沟通冲突，应要求所有团队成员必须使用母语进行工作沟通</li><li>B．文化差异会阻碍团队协作，项目管理团队需尽力消除不同文化间的差异</li><li>C．建设项目团队的核心目标之一是改进成员人际技巧，促进相互信任与充分协作</li><li>D．团队成员来自不同行业，无需保持及时沟通，仅需按各自职责推进工作即可</li></ul><details class="quiz" data-q="115" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O1。顶目经理在全球化环境和富有文化多样性的项目中工作，团队成员经常来自不同的行业，讲不同的语言，有时甚至会在工作中使用一种特别的“团队语言”或文化规范，而不是使用他们的母语；项目管理团队应该利用文化差异，在整个项目生命周期中致力于发展和维护项目团队，并促进在相互信任的氛围中充分协作；通过建设项目团队，可以改进人际技巧、技术能力、团队环境及项目绩效（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q116" class="quiz-anchor"></a></p><p><strong>116.</strong> 能够影响建设团队过程的事业环境因素不包括（ ）。</p><ul><li>A．员工发展与培训记录</li><li>B．认可与奖励相关制度</li><li>C．项目资源分配历史流程</li><li>D．团队成员地理分布情况</li></ul><details class="quiz" data-q="116" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O1。能够影响建设团队过程的事业环境因素包含人力资源管理相关雇佣解雇政策、员工绩效审查、员工发展与培训记录、认可与奖励机制，以及团队成员技能能力、专业知识和地理分布等（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q117" class="quiz-anchor"></a></p><p><strong>117.</strong> 把许多或全部团队成员集中到一个物理地点办公，以增强团队工作能力，是（ ）</p><ul><li>A．预分派</li><li>B．项目团队派工单</li><li>C．虚拟团队</li><li>D．集中办公</li></ul><details class="quiz" data-q="117" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O2。集中办公把许多或全部团队成员集中到一个物理地点办公，以增强团队工作能力（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q118" class="quiz-anchor"></a></p><p><strong>118.</strong> （ ）旨在帮助各团队成员更加有效地协同工作。</p><ul><li>A．冲突管理</li><li>B．影响力</li><li>C．谈判</li><li>D．团队建设</li></ul><details class="quiz" data-q="118" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：团队建设活动旨在帮助各团队成员更加有效地协同工作（P402）　<span class="quiz-src">自编</span></p></details><p><a id="q119" class="quiz-anchor"></a></p><p><strong>119.</strong> 关于建设团队工具和技术的相关描述，不正确的是（ ）。</p><ul><li>A．集中办公可将全部团队成员集中到一个物理地点办公，增强团队工作能力</li><li>B．共享门户、视频会议、音频会议均属于建设团队的沟通技术</li><li>C．正式的沟通和活动有助于建立信任和良好的工作关系</li><li>D．个人和团队评估工具可帮助项目经理洞察成员的优势和劣势</li></ul><details class="quiz" data-q="119" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：非正式的沟通和活动有助于建立信任和良好的工作关系（P402）　<span class="quiz-src">自编</span></p></details><p><a id="q120" class="quiz-anchor"></a></p><p><strong>120.</strong> （ ）能让项目经理和项目团队洞察成员的优势和劣势。</p><ul><li>A．影响力</li><li>B．人际关系与团队技能</li><li>C．情商</li><li>D．个人和团队评估</li></ul><details class="quiz" data-q="120" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：403。个人和团队评估：能让项目经理和项目团队洞察成员的优势和劣费　<span class="quiz-src">自编</span></p></details><p><a id="q121" class="quiz-anchor"></a></p><p><strong>121.</strong> 评价团队有效性的指标，不包括（ ）。</p><ul><li>A．个人技能的改进</li><li>B．团队成员离职率的降低</li><li>C．团队凝聚力的加强</li><li>D．团队成员之间的竞争程度</li></ul><details class="quiz" data-q="121" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：评价团队有效性的指标可包括：①个人技能的改进，使成员更有效地完成工作任务；②团队能力的改进，从面使团队成员更好地开展工作；③团队成员离职率的降低；④团队凝聚力的加强，从而使团队成员公开分享信息和经验，并互相帮助来提高项目绩效（P404）　<span class="quiz-src">自编</span></p></details><p><a id="q122" class="quiz-anchor"></a></p><p><strong>122.</strong> 项目经理被分配管理一个智能型新产品研发项目。项目团队是按照专业知识从不同地方选择的，发现难以管理分处不同地方的项目团队成员后，项目经理申请了一个新地点将团队整合在一起项目经理可使用（ ）技术。</p><ul><li>A．虚拟团队</li><li>B．团队建设</li><li>C．集中办公</li><li>D．基本规则</li></ul><details class="quiz" data-q="122" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「集中办公」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q123" class="quiz-anchor"></a></p><p><strong>123.</strong> （ ）不属于项目团队建设的工具和技巧。</p><ul><li>A．预分派</li><li>B．培训</li><li>C．集中办公</li><li>D．认可和奖励</li></ul><details class="quiz" data-q="123" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A错误。预分派属于获取资源的工具。建设团队的工具与技术包括：1集中办公：2.虚拟团队：3沟通技术（共章门户、视频公议、音频公议、电子邮件/聊天软件）:4.人际关系与团队技能（冲突管理、影响力、激励、谈判、团队建设）;5认可与奖励；6培训；7个人和团队评估：8.会议（P402-403）　<span class="quiz-src">2017 年上半年高项</span></p></details><p><a id="q124" class="quiz-anchor"></a></p><p><strong>124.</strong> （ ）能让项目经理和项目团队洞察成员的优势和劣势。</p><ul><li>A．人际关系技能</li><li>B．项目绩效评估</li><li>C．个人和团队评估</li><li>D．冲突管理</li></ul><details class="quiz" data-q="124" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：个人和团队评估工具能让项目经理和项目团队洞察成员的优势和劣势（P403）　<span class="quiz-src">2019 年下半年高项</span></p></details><p><a id="q125" class="quiz-anchor"></a></p><p><strong>125.</strong> （ ）不是“建设项目团队”过程的输入。</p><ul><li>A．认可与奖励</li><li>B．项目团队派工单</li><li>C．资源日历j</li><li>D．资源管理计划</li></ul><details class="quiz" data-q="125" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O1。认可与奖励属于建设项目团队的工具，一般输入都是各种文件或者环境或者组织资产。建设团队的输入包括：1项目管理计划；2.项目文件（团队章程、项目进度计划、项目团队派工单资源日历、经验教训登记册）;3.事业环境因素；4.组织过程资产（P4）　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q126" class="quiz-anchor"></a></p><p><strong>126.</strong> 团队成员的离职率降低，是（ ）过程的输出。</p><ul><li>A．规划人力资源管理</li><li>B．组建项目团队</li><li>C．建设项目团队</li><li>D．管理项目团队</li></ul><details class="quiz" data-q="126" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O4。评价团队有效性的指标可包括：①个人技能的改进，使成员更有效地完成工作任务；②团队能力的改进，从面使团队成员更好地开展工作；③团队成员离职率的降低；④团队凝聚力的加强，从面使团队成员公开分享信息和经验，并互相帮助来提高项目绩效（P4）　<span class="quiz-src">2021 年下半年高项</span></p></details><p><a id="q127" class="quiz-anchor"></a></p><p><strong>127.</strong> 项目经理为了使团队高效运行并达成项目目标，可采用的方式不包含（ ）</p><ul><li>A．提高项目要求并增加每日工作时长，刺激成员创新</li><li>B．每周组织一次知识分享，提高团队成员的知识和技能</li><li>C．每日组织站会，及时收集成员遇到的问题，协作解决</li><li>D．不定期组织聚餐和团建活动，增加团队凝聚力</li></ul><details class="quiz" data-q="127" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「提高项目要求并增加每日工作时长，刺激成员创新」，原解析未给课本依据　<span class="quiz-src">2022 年上半年高项</span></p></details><p><a id="q128" class="quiz-anchor"></a></p><p><strong>128.</strong> 建设项目团队的目标不包括（ ）。</p><ul><li>A．提高团队成员的知识和技能</li><li>B．减少团队成员间的文化差异</li><li>C．创建富有凝聚力的团队文化</li><li>D．提高团队成员之间的认同感</li></ul><details class="quiz" data-q="128" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O1。建设项目团队的目标包括：①提高团队成员的知识和技能②提高团队成员之间的信任和认同感③创建富有生气、凝聚力和协作性的团队文化④提高团队参与决策的能力（P4）　<span class="quiz-src">2022 年下半年高项</span></p></details><p><a id="q129" class="quiz-anchor"></a></p><p><strong>129.</strong> 适用于建设团队过程的人际关系与团队技能不包括（ ）。</p><ul><li>A．冲突管理</li><li>B．影响力</li><li>C．团队建设</li><li>D．虚拟团队</li></ul><details class="quiz" data-q="129" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O2。适用于建设团队过程的人际关系与团队技能主要包括：(1)冲突管理(2)影响力(3)激励(4)谈判(5)团队建设（P4）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q130" class="quiz-anchor"></a></p><p><strong>130.</strong> 建设项目团队主要目标不包括（ ）。</p><ul><li>A．鼓励团队成员相互竞争</li><li>B．提高团队成员的知识和技能</li><li>C．提高团队成员之间的信任和认同感</li><li>D．创建富有生气、凝聚力和协作性的团队文化</li></ul><details class="quiz" data-q="130" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O1。建设项目团队的目标包括：①提高团队成员的知识和技能②提高团队成员之间的信任和认同感③创建富有生气、凝聚力和协作性的团队文化④提高团队参与决策的能力（P4）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q131" class="quiz-anchor"></a></p><p><strong>131.</strong> 关于建设团队过程的描述，不正确的是（ ）。</p><ul><li>A．本过程输入的项目文件主要包括团队章程、项目进度计划、资源日历、项目团队派工单</li><li>B．团队协作是项目成功的关键因素，而建设高效的项目团队是项目经理的主要职责</li><li>C．团队绩效评价是建设团队过程的输入，同时是管理团队过程的输出</li><li>D．适用于本过程的人际关系与团队技能包括：冲突管理、影响力、激励、谈判、团队建设</li></ul><details class="quiz" data-q="131" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：团队绩效评价是建设团队过程的输出，同时作为管理团队过程的输入，而非输出（P403）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q132" class="quiz-anchor"></a></p><p><strong>132.</strong> 建设团队过程中，可实现团队高效运行的行为包括（ ）①定期进行双向信息同步②决策前公开讨论分歧③安排轻松聚餐回避冲突与差异“④让团队成员轮流主持周例公⑤为活跃气氛领导旁观不参与</p><ul><li>A．①②④</li><li>B．②③④</li><li>C．③④⑤</li><li>D．①②③</li></ul><details class="quiz" data-q="132" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O1。可实现团队的高效运行的行为有：①使用开放与有效的沟通；②创造团队建设机遇；③建立团队成员间的信任：④以建设性方式管理冲突；⑤鼓励合作型的问题解决方法：⑥鼓励合作型的决策方法等（P4）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q133" class="quiz-anchor"></a></p><p><strong>133.</strong> 管理项目团队所获得的主要收益体现在（ ）。①指导团队选择和职责分配；②管理冲突；③解决问题；④改进团队协作；⑤影响团队行为</p><ul><li>A．①③⑤</li><li>B．②③④</li><li>C．①③④</li><li>D．②③⑤</li></ul><details class="quiz" data-q="133" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理团队是跟踪团队成员工作表现、提供反馈、解决问题并管理团队变更以优化项目绩效的过程。本过程的主要作用是，影响团队行为、管理冲突以及解决问题（P404）　<span class="quiz-src">自编</span></p></details><p><a id="q134" class="quiz-anchor"></a></p><p><strong>134.</strong> 关于资源管理过程，（ ）描述是不正确的。</p><ul><li>A．获取资源作用是概述和指导资源的选择，将选择的资源分配给相应的活动</li><li>B．管理团队作用是改进团队协作、增强人际关系技能、激励员工、减少摩擦以及提升整体项目绩效</li><li>C．控制资源作用是确保所分配的资源适时、适地可用于项目，资源在不再需要时被释放</li><li>D．规划资源管理作用是根据项目类型和复杂程度确定适用于项目资源的管理方法和管理程度</li></ul><details class="quiz" data-q="134" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：管理团队是限踪团队成员工作表现、提供反馈、解决问题并管理团队变更以优化项目绩效的过程（P404）　<span class="quiz-src">自编</span></p></details><p><a id="q135" class="quiz-anchor"></a></p><p><strong>135.</strong> （ ）是跟踪团队成员工作表现、提供反馈、解决问题并管理团队变更，以优化项目绩效的过程</p><ul><li>A．建设团队</li><li>B．管理团队</li><li>C．控制资源</li><li>D．获取资源</li></ul><details class="quiz" data-q="135" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O4。管理团队是跟踪团队成员工作表现、提供反馈、解法问题并管理团队变更，以优化项目绩效的过程（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q136" class="quiz-anchor"></a></p><p><strong>136.</strong> 管理团队时不需要考虑的依据是（ ）。</p><ul><li>A．工作绩效报告</li><li>B．变更请求</li><li>C．团队章程</li><li>D．团队绩效评价</li></ul><details class="quiz" data-q="136" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B不正确。变更请求是管理团队的输出。管理团队的输入包括：1项目管理计划；2.项目文件（团队章程、问题日志、项目团队派工单、经验教训登记册）;3工作绩效报告；4.团队绩效评价；5.事业环境因素：6.组织过程资产（P405-406）　<span class="quiz-src">自编</span></p></details><p><a id="q137" class="quiz-anchor"></a></p><p><strong>137.</strong> （ ）是为制定决策、采取行动或引起关注所形成的实物或电子工作绩效信息，它包括从进度控制、成本控制、质量控制和范围确认中得到的结果，有助于项目团队管理。</p><ul><li>A．工作绩效数据</li><li>B．工作绩效信息</li><li>C．工作绩效报告</li><li>D．工作绩效制度</li></ul><details class="quiz" data-q="137" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O6。工作绩效报告是为制定决策、采取行动或引起关注所形成的实物或电子工作绩效信息，它包括从进度控制、成本控制、质量控制和范围确认中得到的结果，有助于项目团队管理（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q138" class="quiz-anchor"></a></p><p><strong>138.</strong> （ ）有助于采取措施解决问题、调整沟通方式、解决冲突和改进团队互动</p><ul><li>A．团队绩效评价</li><li>B．工作绩效报告</li><li>C．团队章程</li><li>D．虚拟团队</li></ul><details class="quiz" data-q="138" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O6。项目管理团队应该持续地对项目团队绩效进行正式或非正式的评价。不断地评价项目团队绩效，有助于采取措施解决问题、调整沟通方式、解决冲突和改进团队互动（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q139" class="quiz-anchor"></a></p><p><strong>139.</strong> 将问题推迟到准备充分的时候，或者将问题推给其他人员解决属于冲突管理中的（ ）</p><ul><li>A．撤退/回避</li><li>B．缓和/包容</li><li>C．安协/调解</li><li>D．强迫/命令</li></ul><details class="quiz" data-q="139" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：撤退/回避从实际或潜在冲突中退出，将问题推迟到准备充分的时候，或者将问题推给其他人员解决（P406-407）　<span class="quiz-src">自编</span></p></details><p><a id="q140" class="quiz-anchor"></a></p><p><strong>140.</strong> 关于管理团队冲突解决方法的描述，正确的是（ ）。</p><ul><li>A．撤退/回避是一种永久性的冲突解决方法</li><li>B．缓和/包容强调差异而非一致，为解决冲突而坚持自身观点</li><li>C．妥协/调解可寻找让各方都在一定程度上满意的方案，可能导致“双输”局面</li><li>D．强迫/命令能带来双赢局面，是最理想的冲突解决方法</li></ul><details class="quiz" data-q="140" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：撤退/回避是一种暂时性的冲突解决方法，因此A错误。缓和/包容强调一致而非差异，为维持和谐与关系而退让一步，因此B错误。妥协/调解为了暂时或部分解决冲突，寻找能让各方都在一定程度上满意的方案，这种方法有时会导致“双输”局面，因此C正确、合作/解决问题能带来双赢局面，是最理想的冲突解决方法；强迫/命令是一方赢、一方输的模式，因此D错误（P406-407）　<span class="quiz-src">自编</span></p></details><p><a id="q141" class="quiz-anchor"></a></p><p><strong>141.</strong> （ ）不是管理团队的工具和技术。</p><ul><li>A．情商</li><li>B．影响</li><li>C．领导力</li><li>D．虚拟团队</li></ul><details class="quiz" data-q="141" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：虚拟团队是获取资源的工具和技术。管理团队的工具和技术包括：1人际关系与团队技能（冲突管理、制定决策、情商、影响、领导力）;2.项目管理信息系统；（P406-407）　<span class="quiz-src">自编</span></p></details><p><a id="q142" class="quiz-anchor"></a></p><p><strong>142.</strong> （ ）冲突管理方法是指综合考虑不同的观点和意见，采用合作的态度和开放式对话引导各方达成共识和承诺</p><ul><li>A．妥协/调解</li><li>B．级和/包容</li><li>C．撤退/回避</li><li>D．合作/解决问题</li></ul><details class="quiz" data-q="142" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O7。●合作/解决问题：综合考虑不同的观点和意见，采用合作的态度和开放式对话引导各方达成共识和承诺，这种方法可以带来双赢局面（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q143" class="quiz-anchor"></a></p><p><strong>143.</strong> 进行有效决策需要：（ ）。①着眼于所要达到的目标；②遵循决策流程；③研究环境因素；④分析可用信息；⑤激发团队创造力；6理解风险</p><ul><li>A．①③④</li><li>B．①②⑤</li><li>C．①②③④⑤</li><li>D．①②③④⑤⑥</li></ul><details class="quiz" data-q="143" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O7。进行有效决策需要：①着服于所要达到的目标；②遵循决策流程；③研究环境因素；④分析可用信息；⑤激发团队创造力；⑥理解风险等（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q144" class="quiz-anchor"></a></p><p><strong>144.</strong> （ ）是指识别、评估和管理个人情绪、他人情绪及团体情绪的能力，可帮助项目管理团队减轻团队压力、加强合作。</p><ul><li>A．领导力</li><li>B．情商</li><li>C．影响力</li><li>D．决策能力</li></ul><details class="quiz" data-q="144" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O7。情商指识别、评估和管理个人情绪、他人情绪及团体情绪的能力。项目管理团队能用情商来了解、评估及控制项目团队成员的情绪，预测团队成员的行为，确认团队成员的关注点及跟踪团队成员的问题，来达到减轻压力、加强合作的目的（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q145" class="quiz-anchor"></a></p><p><strong>145.</strong> 在一次项目团队内部会议中，一名成员不同意项目经理的方案，导致会议无法进行。项目经理提出先讨论下一项议题，会后单独与其沟通。项目经理使用的是（ ）。</p><ul><li>A．级和或包容</li><li>B．妥协或调解</li><li>C．强迫或命令</li><li>D．撤退或回避</li></ul><details class="quiz" data-q="145" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「撤退或回避」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q146" class="quiz-anchor"></a></p><p><strong>146.</strong> 在项目进度评审会议上，两位团队成员就某一关键任务的执行方法产生激烈争执，现场气氛紧张。项目经理见状表示：“这个问题我们先搠置，大家先集中讨论下项目风险应对措施，后续再找时间仔细研究执行细节。”项目经理采用的冲突解决方法是（ ）。</p><ul><li>A．级和/包容</li><li>B．妥协/调解</li><li>C．强迫/命令</li><li>D．撤退/回避</li></ul><details class="quiz" data-q="146" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「撤退/回避」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q147" class="quiz-anchor"></a></p><p><strong>147.</strong> 产生冲突，沟通之后达成一致意见，属于（ ）过程。</p><ul><li>A．建设团队</li><li>B．管理团队</li><li>C．规划资源管理</li><li>D．控制资源</li></ul><details class="quiz" data-q="147" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：，管理团队是跟踪团队成员工作表现、提供反馈、解决问题并管理团队变更，以优化项目绩效的过程。本过程的主要作用是，影响团队行为、管理冲突以及解决问题（P404）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q148" class="quiz-anchor"></a></p><p><strong>148.</strong> （ ）是指识别、评估和管理个人情绪、他人情绪及团体情绪的能力。</p><ul><li>A．情商</li><li>B．影响力</li><li>C．领导力</li><li>D．制定决策</li></ul><details class="quiz" data-q="148" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：情商指识别、评估和管理个人情绪、他人情绪及团体情绪的能力（P407）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q149" class="quiz-anchor"></a></p><p><strong>149.</strong> 管理团队常用的冲突解决方法中，采用（ ）可以获得双赢的局面。</p><ul><li>A．撤退/回避</li><li>B．强迫/命令</li><li>C．合作/解决问题</li><li>D．缓和/包容</li></ul><details class="quiz" data-q="149" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：合作/解决问题可以获得双赢的局面，强迫/金令和缓和/包容通常是一输一赢的局面，撤退/回避问题没有解决（P407）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q150" class="quiz-anchor"></a></p><p><strong>150.</strong> （ ）冲突管理方法是指综合多方面的观点和意见，得到一个多数人能够接受的解决方案</p><ul><li>A．强制</li><li>B．妥协</li><li>C．合作</li><li>D．回避</li></ul><details class="quiz" data-q="150" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：5种常用的冲突解决方法【必须掌握】释义方法类型将问题推迟到准备充分的时候，或者将问题推给其他人员解决。撒退是一种暂撤退/回避 时性的冲突解决方法，强调一致而非差异；为维持和谱wo与niu关系而退让一步（P406-407）　<span class="quiz-src">2016 年下半年高项</span></p></details><p><a id="q151" class="quiz-anchor"></a></p><p><strong>151.</strong> 为了暂时或部分解决冲突，寻找能让各方在一定程度上都满意的方案。这种冲突解决方法称为（ ）。</p><ul><li>A．妥协/调解</li><li>B．缓和/包容</li><li>C．撤退/回避</li><li>D．合作/解决问题</li></ul><details class="quiz" data-q="151" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：5种常用的冲突解决方法【必须掌握】释义方法类型将问题推迟到准备充分的时候，或者将问题推给其他人员解决。撒退是一种暂撤退/回避 时性的冲突解决方法，强调一致而非差异；为维持和谐与关系而退让一步（P406-407）　<span class="quiz-src">2020 年下半年高项</span></p></details><p><a id="q152" class="quiz-anchor"></a></p><p><strong>152.</strong> 项目管理信息系统包括（ ）软件，用于监督资源的使用情况，协助确保合适的资源适时、适地用于合适的活动。</p><ul><li>A．资源管理或进度计划</li><li>B．CRM系统</li><li>C．采购系统或智能分析</li><li>D．BOM系统</li></ul><details class="quiz" data-q="152" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O7。项目管理信息系统可包括资源管理或进度计划软件，用于监督资源的使用情况，协助确保合适的资源适时、适地用于合适的活动（P4）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q153" class="quiz-anchor"></a></p><p><strong>153.</strong> 关于项目资源管理过程的相关描述，不正确的是（ ）。</p><ul><li>A．建设团队过程用于跟踪团队成员工作表现，提供反馈，解决问题，以优化项目绩效</li><li>B．规划资源管理过程用于定义如何估算、获取、管理和利用实物以及团队项目资源</li><li>C．获取资源过程用于获取项目所需的团队成员、设施、设备、材料、用品和其他资源</li><li>D．估算活动资源过程用于估算执行项目所需的团队资源，以及材料、设备和用品的类型和数量</li></ul><details class="quiz" data-q="153" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：管理团队是跟踪团队成员工作表现、提供反馈、解决问题并管理团队变更以优化项目绩效的过程（P404）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q154" class="quiz-anchor"></a></p><p><strong>154.</strong> 在管理团队过程的人际关系与团队技能中，项目经理对项目团队的影响力主要体现在（ ）①说服他人②预测团队成员的行为&quot;③了解并综合考虑各种观点④收集相关信息，在维护相互信任的关系下，解决问题并达成一致意见</p><ul><li>A．②③④</li><li>B．①④</li><li>C．①②④</li><li>D．①2</li></ul><details class="quiz" data-q="154" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O7。影响力主要体现在如下方面：说服他人；清断表达观点和立场；积极且有效的倾听；了解并综合考虑各种观点；收集相关信息，在维护相互信任的关系下，解决问题并达成一致意见等（P4）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q155" class="quiz-anchor"></a></p><p><strong>155.</strong> 开发团队就前端框架选用方案A还是方案B争执不下，项目经理宜布“先按现有技术开发原型，两周后的技术评审会再定”。项目经理采取的冲突解决方法是（ ）。</p><ul><li>A．缓和或包容</li><li>B．撤退或回避</li><li>C．妥协或调解</li><li>D．强迫或命令</li></ul><details class="quiz" data-q="155" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：有5种常用的冲突解决方法，每种技巧都有各自的作用和用途●撤退/回避：从实际或潜在冲突中退出，将问题推迟到准备充分的时候，或者将问题推给其他人员解决（P406-407）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q156" class="quiz-anchor"></a></p><p><strong>156.</strong> 确保所分配的资源适时、适地可用于项目，是（ ）过程的主要作用。</p><ul><li>A．建设团队</li><li>B．管理团队</li><li>C．控制资源</li><li>D．获取资源</li></ul><details class="quiz" data-q="156" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O8。控制资源的作用：①确保所分配的资源适时、适地可用于项目；②资源在不再需要时被释放（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q157" class="quiz-anchor"></a></p><p><strong>157.</strong> 下面属于控制资源过程的依据的是（ ）。</p><ul><li>A．工作绩效数据</li><li>B．工作绩效信息</li><li>C．工作绩效报告</li><li>D．变更请求</li></ul><details class="quiz" data-q="157" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：只有A是控制资源的输入。控制资源的输入包括：1项目管理计划；2.项目文件（项目进度计划、问题日志、资源需求、资源分解结构、经验教训登记册、物质资源分配单、风险登记册）3.工作绩效数据；4.协议；5.组织过程资产（P409）　<span class="quiz-src">自编</span></p></details><p><a id="q158" class="quiz-anchor"></a></p><p><strong>158.</strong> （ ）不属于控制资源关注的内容。</p><ul><li>A．及时识别和处理资源缺乏/剩余情况，监督资源支出</li><li>B．出现资源相关问题时通知相应干系人</li><li>C．监督团队建设的绩效情况</li><li>D．确保根据计划和项目需求使用并释放资源</li></ul><details class="quiz" data-q="158" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：控制资源过程关注：①监督资源支出；②及时识别和处理资源缺乏/剩余情况；③确保根据计划和项目霞求使用并释放资源；④出现资源相关问题时通知相应干系人；⑥影响可以导致资源使用变更的因素；6在变更实际发生时对其进行管理等（P409）　<span class="quiz-src">自编</span></p></details><p><a id="q159" class="quiz-anchor"></a></p><p><strong>159.</strong> 项目中的设备、材料、设施和基础设施属于（ ）。</p><ul><li>A．实物资源</li><li>B．人力资源</li><li>C．设备资源</li><li>D．基础资源</li></ul><details class="quiz" data-q="159" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O9。控制资源过程重点关注实物资源，例如设备、材料、设施和基础设施。管理团队过程重点关注人力资源（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q160" class="quiz-anchor"></a></p><p><strong>160.</strong> （ ）不属于控制资源关注的内容。</p><ul><li>A．及时识别和处理资源缺乏/剩余情况</li><li>B．出现资源相关问题时通知相应干系人</li><li>C．监督项目进度计划的执行情况</li><li>D．确保根据计划和项目需求使用并释放资源</li></ul><details class="quiz" data-q="160" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O9。控制资源过程关注：①监督资源支出；②及时识别和处理资源然乏/剩余情况；③确保根据计划和项目需求使用并释放资源；④出现资源相关问题时通知相应干系人；⑤影响可以导致资源使用变更的因素；⑥在变更实际发生时对其进行管理等（P4）　<span class="quiz-src">自编</span></p></details><p><a id="q161" class="quiz-anchor"></a></p><p><strong>161.</strong> （ ）检查项目绩效随时间的变化情况，可用于确定绩效是在改善还是在恶化。</p><ul><li>A．备选方案分析</li><li>B．成本效益分析</li><li>C．绩效审查</li><li>D．趋势分析</li></ul><details class="quiz" data-q="161" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：趋势分析检查项目绩效随时间的变化情况，可用于确定绩效是在改善还是在恶化（P410）　<span class="quiz-src">自编</span></p></details><p><a id="q162" class="quiz-anchor"></a></p><p><strong>162.</strong> 软技能”属于（ ）。</p><ul><li>A．领导力</li><li>B．沟通能力</li><li>C．个人能力</li><li>D．影响力</li></ul><details class="quiz" data-q="162" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：人际关系与团队技能有时被称为“软技能”，属于个人能力（P410）　<span class="quiz-src">自编</span></p></details><p><a id="q163" class="quiz-anchor"></a></p><p><strong>163.</strong> 在控制资源过程中，（ ）用于测量、比较和分析计划的资源使用和实际资源使用的不同</p><ul><li>A．备选方案分析</li><li>B．成本效益分析</li><li>C．绩效审查</li><li>D．趋势分析</li></ul><details class="quiz" data-q="163" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：备选方案分析：有助于选择最佳解决方案以纠正资源使用偏差。成本效益分析：有助于项目成本出现差异时确定最佳的纠正措施绩效审查：测量、比较和分析计划的资源使用和实际资源使用的不同（P410）　<span class="quiz-src">自编</span></p></details><p><a id="q164" class="quiz-anchor"></a></p><p><strong>164.</strong> 问题解决的步骤是（ ）。①识别问题；②定义问题；③调查；④分析，找出问题的根本原因；⑤解决，从众多解决方案中选择最合适的一个；⑥检查解决方案，确认是否已解决问题</p><ul><li>A．③②①④⑤⑥</li><li>B．②①3④⑤6</li><li>C．①②③④⑥5</li><li>D．①②③④⑤⑥)</li></ul><details class="quiz" data-q="164" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理应采取有条不亲的步骤来解决问题：①识别问题。②定义问题。③调查。④分析，找出问题的根本原因。⑤解决，从众多解决方案中选择最合适的一个（P410）　<span class="quiz-src">自编</span></p></details><p><a id="q165" class="quiz-anchor"></a></p><p><strong>165.</strong> 某项目执行过程中，项目经理通过监控发现，部分实物资源实际使用量远超计划用量，且出现资源浪费、成本超支的问题，需要选择最佳纠正措施来解决该偏差。此时最适合采用的控制资源工具是（ ）。</p><ul><li>A．趋势分析，检查资源使用绩效随时间的变化情况</li><li>B．成本效益分析，确定解决成本超支和资源浪费的最佳纠正措施</li><li>C．谈判，与资源供应商协商减少资源供应数量</li><li>D．问题解决，直接停止部分实物资源的使用以控制成本</li></ul><details class="quiz" data-q="165" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：综上，B最合适（P41）　<span class="quiz-src">自编</span></p></details><p><a id="q166" class="quiz-anchor"></a></p><p><strong>166.</strong> （ ）是获取组织外部资源的依据。</p><ul><li>A．资源分解结构</li><li>B．物质资源分配单</li><li>C．在项目中签署的协议</li><li>D．工作绩效数据</li></ul><details class="quiz" data-q="166" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在项目中签署的协议是获取组织外部资源的依据，应在需要新的和未规划的资源时，或在当前资源出现问题时，在协议里定义相关程序（P409）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q167" class="quiz-anchor"></a></p><p><strong>167.</strong> 关于控制资源的描述，不正确的是（ ）。</p><ul><li>A．控制资源用于确保按计划为项目分配实物资源</li><li>B．控制资源需要在整个项目期间开展</li><li>C．控制资源过程需关注监督资源支出</li><li>D．控制资源结束统一释放回收资源</li></ul><details class="quiz" data-q="167" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制资源是确保按计划为项目分配实物资源，以及根据资源使用计划监督资源实际使用情况，并采取必要纠正措施的过程。本过程的主要作用：①确保所分配的资激适时、适地可用于项目；②资源在不再需要时被释放（P408）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q168" class="quiz-anchor"></a></p><p><strong>168.</strong> 控制资源过程关注的内容不包括（ ）。</p><ul><li>A．监督资源支出</li><li>B．在变更实际发生时对其进行管理</li><li>C．出现资源相关问题时通知相应干系人</li><li>D．持续评估工作职责的落实情况</li></ul><details class="quiz" data-q="168" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制资源过程关注：①监督资源支出；②及时识别和处理资源缺乏/剩余情况；③确保根据计划和项目需求使用并释放资源；④出现资源相关问题时通知相应干系人⑤影响可以导致资源使用变更的因素；⑥在变更实际发生时对其进行管理等（P409）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q169" class="quiz-anchor"></a></p><p><strong>169.</strong> 控制资源是（ ），以及根据资源使用计划监督资源实际使用情况，并采取必要纠正措施的过程</p><ul><li>A．确保按计划为项目分配实物资源</li><li>B．概述和指导资源的选择</li><li>C．明确完成项目所需的资源种类、数量和特性</li><li>D．影响可以导致资源使用变更的因素</li></ul><details class="quiz" data-q="169" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制资源是确保按计划为项目分配实物资源，以及根据资源使用计划监督资源实际使用情况，并采取必要纠正措施的过程。本过程的主要作用：①确保所分配的资源适时、适地可用于项目；②资源在不再需要时被释放（P408）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q170" class="quiz-anchor"></a></p><p><strong>170.</strong> 某公司人员流动性强，最近频频发生人员的变更。作为公司项目经理，此时需要处理的事项不包含（ ）。</p><ul><li>A．变更项目管理计划</li><li>B．变更问题描述和项目人员分派文件</li><li>C．更新项目范围和目标</li><li>D．总结历史信息和经验教训文档</li></ul><details class="quiz" data-q="170" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「更新项目范围和目标」，原解析未给课本依据　<span class="quiz-src">2022 年上半年高项</span></p></details><p><a id="q171" class="quiz-anchor"></a></p><p><strong>171.</strong> （ ）过程的主要作用是确保所分配的资源可适时、适地用于项目</p><ul><li>A．规划资源</li><li>B．获取资源</li><li>C．估算活动资源</li><li>D．控制资源</li></ul><details class="quiz" data-q="171" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O8。控制资源的作用：①确保所分配的资源适时、适地可用于项目；②资源在不再需要时被释放（P4）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q172" class="quiz-anchor"></a></p><p><strong>172.</strong> 控制资源是确保按计划为项目分配（ ）资源，以及根据资源使用计划监督资源实际使用情况。并采取必要纠正措施的过程。</p><ul><li>A．实物</li><li>B．人力</li><li>C．人力和实物</li><li>D．财务</li></ul><details class="quiz" data-q="172" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O8。控制资源是确保按计划为项目分配实物资源，以及根据资源使用计划监督资源实际使用情况。并采取必要纠正措施的过程，（P4）　<span class="quiz-src">2023 年下半年高项第 3 批</span></p></details><p><a id="q173" class="quiz-anchor"></a></p><p><strong>173.</strong> （ ）不是控制资源过程的输入。</p><ul><li>A．工作绩效信息</li><li>B．物质资源分配单</li><li>C．问题日志</li><li>D．风险登记册</li></ul><details class="quiz" data-q="173" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：工作绩效信息是除整合管理外的所有监控过程的输出控制资源过程的输入：1.项目管理计划2.项目文件（●项目进度计划●问题日志●资源需求●资源分解结构●经验教训登记册●物质资源分配单●风险登记册）3.工作绩效数据4.协议5组织过程资产（P410）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q174" class="quiz-anchor"></a></p><p><strong>174.</strong> 在控制资源过程中，项目经理发现某实物资源使用效率远低于计划，首先应采取的措施是（ ）</p><ul><li>A．分析资源低效使用的根本原因</li><li>B．调整项目进度计划以匹配资源</li><li>C．减少该资源的整体投入量</li><li>D．立即更换该资源的使用人员</li></ul><details class="quiz" data-q="174" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目经理应采取有条不素的步骤来解决问题：①识别问题：明痛问题。②定义问题：将问题分解为可管理的小问题。③调查：收集数据（P410）　<span class="quiz-src">2026 年高项第 1 批</span></p></details></div>`,1)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};